import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.asarray(grid, dtype=int)
    h, w = arr.shape
    if h == 0 or w == 0:
        return [[0] * w for _ in range(h)]

    # Find the vertical separator column: a constant non-zero colour.
    # Prefer the colour that also appears elsewhere (examples use 2/3/4).
    candidates = []
    for c in range(w):
        col = arr[:, c]
        if col.min() != col.max() or col[0] == 0:
            continue
        color = int(col[0])
        candidates.append((int((arr == color).sum()), c))

    if candidates:
        # Most frequent separator colour; tie -> leftmost.
        sep_col = max(candidates, key=lambda x: (x[0], -x[1]))[1]
    else:
        # Fallback: first constant non-zero column, or none.
        sep_col = None
        for c in range(w):
            col = arr[:, c]
            if col.min() != col.max() or col[0] == 0:
                continue
            sep_col = c
            break

    if sep_col is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    right_len = w - (sep_col + 1)
    if right_len <= 0:
        return out

    for r in range(h):
        # Extract cells left of the separator.
        left = arr[r, :sep_col].tolist()
        if all(v == 0 for v in left):
            continue

        # Split into contiguous non-zero blocks.
        blocks = []  # (priority, length, color); priority 0 = closest to separator
        priority = 0
        i = len(left) - 1
        while i >= 0:
            if left[i] != 0:
                color = left[i]
                length = 0
                while i >= 0 and left[i] == color:
                    length += 1
                    i -= 1
                blocks.append((priority, length, color))
                priority += 1
            else:
                i -= 1

        # Generate the right side by overlapping periodic pulses from all blocks.
        # Closer blocks override farther ones; pulse period is the block length.
        for j in range(right_len):
            val = 0
            for prio, length, color in blocks:
                if j % length == 0:
                    val = color
                    break  # higher priority already selected
            out[r][sep_col + 1 + j] = int(val)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape

    # The horizontal "spine" is the row containing the most 6s.
    spine_row = int(np.argmax(a.sum(axis=1)))

    # A vertical bar is a maximal vertical run of the same non-8, non-6 color
    # that includes the spine row.
    bars = []
    for c in range(W):
        color = a[spine_row, c]
        if color == 8 or color == 6:
            continue

        r0 = spine_row
        while r0 > 0 and a[r0 - 1, c] == color:
            r0 -= 1
        r1 = spine_row
        while r1 < H - 1 and a[r1 + 1, c] == color:
            r1 += 1

        if (r1 - r0) % 2 == 0 and a[(r0 + r1) // 2, c] == color:
            half = (r1 - r0) // 2
            bars.append((c, color, r0, r1, half))

    if not bars:
        return a.tolist()

    # Sort the vertical half-lengths ascending and assign them left-to-right.
    new_halves = sorted(b[4] for b in bars)

    result = a.copy()

    for (c, color, r0, r1, old_half), new_half in zip(bars, new_halves):
        if new_half == old_half:
            continue

        center = (r0 + r1) // 2
        # Remove old bar.
        for r in range(max(0, center - old_half), min(H, center + old_half + 1)):
            if result[r, c] == color:
                result[r, c] = 8

        # Draw new bar.
        for r in range(max(0, center - new_half), min(H, center + new_half + 1)):
            result[r, c] = color

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Central horizontal line is the row with the most 6s.
    six_counts = (a == 6).sum(axis=1)
    center = int(np.argmax(six_counts))

    bars = []
    for c in range(W):
        color = a[center, c]
        if color == 8 or color == 6:
            continue

        # Extend vertically while the same color continues.
        top = center
        while top > 0 and a[top - 1, c] == color:
            top -= 1

        bottom = center
        while bottom < H - 1 and a[bottom + 1, c] == color:
            bottom += 1

        half = max(center - top, bottom - center)
        bars.append((c, color, top, bottom, half))

    if not bars:
        return a.tolist()

    new_halves = sorted(b[4] for b in bars)

    result = a.copy()

    for (c, color, top, bottom, old_half), new_half in zip(bars, new_halves):
        if new_half == old_half:
            continue

        # Clear the old vertical bar in this column.
        r0 = max(0, center - old_half)
        r1 = min(H - 1, center + old_half)
        for r in range(r0, r1 + 1):
            if result[r, c] == color:
                result[r, c] = 8

        # Draw the new vertical bar.
        r0 = max(0, center - new_half)
        r1 = min(H - 1, center + new_half)
        for r in range(r0, r1 + 1):
            result[r, c] = color

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    # The input examples are vertically banded: each row is a solid color.
    # Compress consecutive identical rows into (color, height) bands.
    bands = []
    prev = None
    count = 0

    for row in grid:
        color = row[0]
        if color == prev:
            count += 1
        else:
            if prev is not None:
                bands.append((prev, count))
            prev = color
            count = 1
    bands.append((prev, count))

    total_h = sum(h for _, h in bands)

    # Output is a square. Its side is 2 * number of input rows - 2.
    n = 2 * total_h - 2
    out = [[0] * n for _ in range(n)]

    offset = 0

    # Draw concentric filled squares from outside to inside.
    # For a band of height h, the current square shrinks by 2*h after it is drawn.
    for i, (color, h) in enumerate(bands):
        side = n - 2 * offset
        if side <= 0:
            break

        if i == len(bands) - 1:
            # Final band fills the remaining center square.
            for r in range(offset, offset + side):
                out[r][offset:offset + side] = [color] * side
        else:
            # Fill the whole current square with this band color;
            # inner squares will overwrite its center later.
            for r in range(offset, offset + side):
                out[r][offset:offset + side] = [color] * side

        offset += h

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    def cells_of(color):
        return [(r, c) for r in range(h) for c in range(w) if g[r, c] == color]

    def is_complete_block(color, r0, c0):
        if r0 < 0 or c0 < 0 or r0 + 3 > h or c0 + 3 > w:
            return False
        for dr in range(3):
            for dc in range(3):
                if g[r0 + dr, c0 + dc] != color:
                    return False
        return True

    def component_size(color, start):
        seen = {start}
        q = deque([start])
        size = 0
        r, c = start
        while q:
            r, c = q.popleft()
            size += 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == color and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return size, seen

    best = None
    for r in range(h):
        for c in range(w):
            color = g[r, c]
            if color == 0:
                continue

            ok = False
            for dr in (-2, -1, 0):
                for dc in (-2, -1, 0):
                    if is_complete_block(color, r + dr, c + dc):
                        ok = True
            if not ok:
                continue

            size, comp = component_size(color, (r, c))
            if best is None or size > best[0]:
                best = (size, color, comp)

    if best is None:
        return [[0 for _ in range(w)] for _ in range(h)]

    size, color, comp = best
    r0 = min(r for r, _ in comp)
    r1 = max(r for r, _ in comp)
    c0 = min(c for _, c in comp)
    c1 = max(c for _, c in comp)

    out = [[0 for _ in range(c1 - c0 + 1)] for _ in range(r1 - r0 + 1)]
    for r, c in comp:
        out[r - r0][c - c0] = int(color)
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque
    import numpy as np

    a = np.asarray(grid, dtype=int)
    h, w = a.shape
    if h == 0 or w == 0:
        return []

    best = None  # (size, top, left, bottom, right)
    visited = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if a[r, c] == 0 or visited[r, c]:
                continue

            color = a[r, c]
            q = deque([(r, c)])
            visited[r, c] = True
            min_r = max_r = r
            min_c = max_c = c
            size = 0

            while q:
                y, x = q.popleft()
                size += 1
                if y < min_r:
                    min_r = y
                if y > max_r:
                    max_r = y
                if x < min_c:
                    min_c = x
                if x > max_c:
                    max_c = x

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny, nx] and a[ny, nx] == color:
                            visited[ny, nx] = True
                            q.append((ny, nx))

            if best is None or size > best[0]:
                best = (size, min_r, min_c, max_r, max_c)

    if best is None:
        return [[0] * w for _ in range(h)]

    _, r0, c0, r1, c1 = best
    return a[r0:r1 + 1, c0:c1 + 1].tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

    h = len(grid)
    w = len(grid[0]) if h else 0
    if h == 0 or w == 0:
        return []

    visited = [[False] * w for _ in range(h)]
    best = None  # (size, top, left, bottom, right, cells)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            q = deque([(r, c)])
            visited[r][c] = True
            cells = [(r, c)]
            top, left, bottom, right = r, c, r, c

            while q:
                y, x = q.popleft()
                if y < top:
                    top = y
                if x < left:
                    left = x
                if y > bottom:
                    bottom = y
                if x > right:
                    right = x

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny][nx] and grid[ny][nx] == color:
                            visited[ny][nx] = True
                            cells.append((ny, nx))
                            q.append((ny, nx))

            size = len(cells)
            if best is None or size > best[0]:
                best = (size, top, left, bottom, right, cells)

    if best is None:
        return [[0] * w for _ in range(h)]

    _, top, left, bottom, right, cells = best
    out = [[0] * (right - left + 1) for _ in range(bottom - top + 1)]
    for r, c in cells:
        out[r - top][c - left] = grid[r][c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    out = [row[:] for row in grid]

    # For each horizontal 7-run (all examples use runs of length 3),
    # replace it by 8 6 8.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 7:
                start = c
                while c < w and grid[r][c] == 7:
                    c += 1
                run_len = c - start
                if run_len >= 1:
                    out[r][start + run_len // 2] = 6
                    for cc in range(start, c):
                        if cc != start + run_len // 2:
                            out[r][cc] = 8
            else:
                c += 1

    # Propagate the 6 centers vertically through straight 8-paths.
    # Only cells whose original value was 8 may become 6.
    for c in range(w):
        for r in range(1, h):
            if out[r][c] == 6 and grid[r + 1][c] == 8:
                out[r + 1][c] = 6
        for r in range(h - 2, -1, -1):
            if out[r][c] == 6 and grid[r - 1][c] == 8:
                out[r - 1][c] = 6

    # Propagate 3 endpoints along 8/3 paths, except into cells marked 6.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 3:
                left = c
                right = c
                while left - 1 >= 0 and out[left - 1][c] != 6 and grid[r][left - 1] in (8, 3):
                    left -= 1
                while right + 1 < w and out[right + 1][c] != 6 and grid[r][right + 1] in (8, 3):
                    right += 1
                for cc in range(left, right + 1):
                    if grid[r][cc] != 6:
                        out[r][cc] = 3
                c = right + 1
            else:
                c += 1

    return out

