def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.asarray(grid, dtype=int)
    h, w = a.shape

    # Background: most common colour in the first row.
    bg = int(np.argmax(np.bincount(a[0].ravel(), minlength=10)))

    # Marker: the colour-4 cells.
    ys, xs = np.where(a == 4)
    y0 = int(ys.min())
    x0 = int(xs.min())
    x1 = int(xs.max())
    marker_w = x1 - x0 + 1
    period = 2 * marker_w

    # Object colour: any non-background colour that is not 4.
    vals, counts = np.unique(a, return_counts=True)
    obj = None
    for v, c in zip(vals, counts):
        if v != bg and v != 4 and c > 0:
            obj = int(v)
            break

    out = a.copy()

    # Vertical periodic marker pattern in the marker column span.
    for r in range(h):
        m = r % period
        if m == 0:
            fill = 3
        elif m in (2, 4):
            fill = 4
        else:
            fill = bg

        span = out[r, x0:x1 + 1]
        if fill == 4 and np.all(span == 4):
            continue
        out[r, x0:x1 + 1] = np.where(span == 4, 4, fill)

    # Recolour object components whose top row parity matches marker top row parity.
    if obj is not None:
        visited = np.zeros((h, w), dtype=bool)
        target_parity = y0 % 2

        for r in range(h):
            for c in range(w):
                if a[r, c] != obj or visited[r, c]:
                    continue

                # Flood fill 8-connected component.
                stack = [(r, c)]
                visited[r, c] = True
                comp = []
                top = r

                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    if rr < top:
                        top = rr
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = rr + dr, cc + dc
                            if (
                                0 <= nr < h
                                and 0 <= nc < w
                                and not visited[nr, nc]
                                and a[nr, nc] == obj
                            ):
                                visited[nr, nc] = True
                                stack.append((nr, nc))

                if top % 2 == target_parity:
                    for rr, cc in comp:
                        out[rr, cc] = 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Background is the dominant colour in the first row.
    bg = max(set(grid[0]), key=grid[0].count)

    # The marker colour is always 4.
    marker_ys, marker_xs = [], []
    obj_color = None

    # Find the marker and infer the object colour as the only non-background, non-4 colour.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 4:
                marker_ys.append(r)
                marker_xs.append(c)
            elif v != bg and v != 4 and obj_color is None:
                obj_color = v

    top = min(marker_ys)
    left = min(marker_xs)
    right = max(marker_xs)

    out = [row[:] for row in grid]

    # Vertical periodic pattern in the marker's column span:
    # row % 6 == 0 -> 3, row % 6 in {2, 4} -> 4, otherwise background.
    for r in range(len(grid)):
        m = r % 6
        if m == 0:
            fill = 3
        elif m in (2, 4):
            fill = 4
        else:
            fill = bg

        # Do not overwrite the original marker cells.
        for c in range(left, right + 1):
            if grid[r][c] != 4:
                out[r][c] = fill

    # On rows congruent to the marker's top row modulo 6, convert all object cells to 3.
    if obj_color is not None:
        for r in range(len(out)):
            if r % 6 == top % 6:
                for c in range(len(out[r])):
                    if out[r][c] == obj_color:
                        out[r][c] = 3

    return out

