    colors = {grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != 0 and grid[r][c] != 1}

    # 1) Fill every background cell horizontally between two equal non-1 wall colors
    #    in the same row.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                left = right = None
                d = 1
                while c - d >= 0 and grid[r][c - d] == 0:
                    d += 1
                if c - d >= 0:
                    left = grid[r][c - d]
                d = 1
                while c + d < w and grid[r][c + d] == 0:
                    d += 1
                if c + d < w:
                    right = grid[r][c + d]
                if left is not None and left == right and left != 1:
                    grid[r][c] = 1

    # 2) Remove 1-cells that are "unsupported": a 1 at (r, c) is kept only if it
    #    is horizontally between two equal non-1 wall colors, or if it is adjacent
    #    (including diagonally) to such a supported 1-cell.
    keep = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            left = right = None
            d = 1
            while c - d >= 0 and grid[r][c - d] == 0:
                d += 1
            if c - d >= 0:
                left = grid[r][c - d]
            d = 1
            while c + d < w and grid[r][c + d] == 0:
                d += 1
            if c + d < w:
                right = grid[r][c + d]
            if left is not None and left == right and left != 1:
                keep[r][c] = True

    for r in range(h):
        for c in range(w):
            if not keep[r][c]:
                continue
            for dr in (-1, 0, 1):
                rr = r + dr
                if rr < 0 or rr >= h:
                    continue
                for dc in (-1, 0, 1):
                    cc = c + dc
                    if cc < 0 or cc >= w:
                        continue
                    if grid[rr][cc] == 1:
                        keep[rr][cc] = True

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and not keep[r][c]:
                grid[r][c] = 0

    return grid

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    g = [row[:] for row in grid]

    # 1) Add 1s in empty cells that lie strictly between two equal, non-1 colors
    #    in the same row or same column.
    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] == 0:
            g[r][c] = 1

    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 0 and g[r][c] != 1:
                d = 1
                while c + d < w and g[r][c + d] == 0:
                    d += 1
                if c + d < w and g[r][c + d] == g[r][c]:
                    for cc in range(c + 1, c + d):
                        paint(r, cc)
                c += d
            else:
                c += 1

    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 0 and g[r][c] != 1:
                d = 1
                while r + d < h and g[r + d][c] == 0:
                    d += 1
                if r + d < h and g[r + d][c] == g[r][c]:
                    for rr in range(r + 1, r + d):
                        paint(rr, c)
                r += d
            else:
                r += 1

    # 2) Remove 1-cells that are not in the lower connected component of 1s.
    #    Connectivity is 8-directional; the component that touches the bottom row
    #    (or is adjacent to a bottom-row 1) is kept.
    visited = [[False] * w for _ in range(h)]
    comps = []

    for sr in range(h):
        for sc in range(w):
            if g[sr][sc] == 1 and not visited[sr][sc]:
                stack = [(sr, sc)]
                visited[sr][sc] = True
                comp = []
                while stack:
                    r, c = stack.pop()
                    comp.append((r, c))
                    for dr in (-1, 0, 1):
                        rr = r + dr
                        if rr < 0 or rr >= h:
                            continue
                        for dc in (-1, 0, 1):
                            cc = c + dc
                            if cc < 0 or cc >= w:
                                continue
                            if g[rr][cc] == 1 and not visited[rr][cc]:
                                visited[rr][cc] = True
                                stack.append((rr, cc))
                comps.append(comp)

    keep = [[False] * w for _ in range(h)]
    for comp in comps:
        if any(r == h - 1 for r, c in comp):
            for r, c in comp:
                keep[r][c] = True

    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not keep[r][c]:
                g[r][c] = 0

    return g

