    from collections import deque
    h = len(grid)
    w = len(grid[0])
    g = [row[:] for row in grid]

    # Step 1: Add 1s via directional shading from walls
    # Horizontal: for each wall at (r,c), extend right: skip 1s, paint 0s until non-0
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] not in (0, 1):  # found a wall
                # Extend right
                j = c + 1
                while j < w and g[r][j] == 1:
                    j += 1
                while j < w and g[r][j] == 0:
                    g[r][j] = 1
                    j += 1
                # Extend left
                j = c - 1
                while j >= 0 and g[r][j] == 1:
                    j -= 1
                while j >= 0 and g[r][j] == 0:
                    g[r][j] = 1
                    j -= 1
                c = j + 1 if j >= 0 else c + 1
            else:
                c += 1

    # Vertical: for each wall at (r,c), extend down/up
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] not in (0, 1):  # found a wall
                # Extend down
                j = r + 1
                while j < h and g[j][c] == 1:
                    j += 1
                while j < h and g[j][c] == 0:
                    g[j][c] = 1
                    j += 1
                # Extend up
                j = r - 1
                while j >= 0 and g[j][c] == 1:
                    j -= 1
                while j >= 0 and g[j][c] == 0:
                    g[j][c] = 1
                    j -= 1
                r = j + 1 if j >= 0 else r + 1
            else:
                r += 1

    # Step 2: Remove 1s not in the lower connected component
    # 4-directional connectivity; keep component(s) containing wall-adjacent 1s
    keep = [[False] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in range(w):
            if g[r][c] == 1:
                # Check if adjacent (4-dir) to a wall
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    rr, cc = r+dr, c+dc
                    if 0 <= rr < h and 0 <= cc < w and g[rr][cc] not in (0, 1):
                        keep[r][c] = True
                        seen[r][c] = True
                        q.append((r, c))
                        break

    while q:
        r, c = q.popleft()
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            rr, cc = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc < w and g[rr][cc] == 1 and not seen[rr][cc]:
                seen[rr][cc] = True
                keep[rr][cc] = True
                q.append((rr, cc))

    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not keep[r][c]:
                g[r][c] = 0

    return g

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    def line_color(p, q):
        x1, y1 = p
        x2, y2 = q
        dx, dy = x2 - x1, y2 - y1
        g = math.gcd(abs(dx), abs(dy))
        if g == 0:
            return 0
        sx = dx // g
        sy = dy // g
        x, y = x1, y1
        while (x, y) != (x2, y2):
            x += sx
            y += sy
            if 0 <= x < w and 0 <= y < h:
                return out[y][x]
        return 0

    def same_pair(p, q):
        x1, y1 = p
        x2, y2 = q
        if line_color(p, q) == 0:
            return True
        return line_color(p, q) == grid[y1][x1] == grid[y2][x2]

    def draw_line(p, q, c):
        x1, y1 = p
        x2, y2 = q
        dx, dy = x2 - x1, y2 - y1
        steps = max(abs(dx), abs(dy))
        if steps == 0:
            out[y1][x1] = c
            return
        for i in range(steps + 1):
            x = round(x1 + dx * i / steps)
            y = round(y1 + dy * i / steps)
            if 0 <= x < w and 0 <= y < h:
                out[y][x] = c

    def draw_bbox(pts, c):
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        x1, x2 = min(xs), max(xs)
        y1, y2 = min(ys), max(ys)
        for y in range(y1, y2 + 1):
            for x in (x1, x2):
                if 0 <= x < w and 0 <= y < h:
                    out[y][x] = c
        for x in range(x1, x2 + 1):
            for y in (y1, y2):
                if 0 <= x < w and 0 <= y < h:
                    out[y][x] = c

    colors = {}
    for y in range(h):
        for x in range(w):
            v = grid[y][x]
            if v:
                colors.setdefault(v, []).append((x, y))

    for c, pts in colors.items():
        if len(pts) < 2:
            continue

        pairs = []
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                if same_pair(pts[i], pts[j]):
                    pairs.append((pts[i], pts[j]))

        if len(pts) >= 4:
            draw_bbox(pts, c)

        if pairs:
            for a, b in pairs:
                draw_line(a, b, c)

        if len(pts) >= 3:
            for i in range(len(pts)):
                a, b, d = pts[i - 1], pts[i], pts[(i + 1) % len(pts)]
                if same_pair(a, b) and same_pair(b, d):
                    draw_line(a, d, c)

    return out

