def transform(grid: list[list[int]]) -> list[list[int]]:
    def bres(p, q):
        x0, y0 = p
        x1, y1 = q
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        cells = []
        while True:
            cells.append((x0, y0))
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy
        return cells

    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    colors = {}
    for y in range(h):
        for x in range(w):
            v = grid[y][x]
            if v:
                colors.setdefault(v, []).append((x, y))

    for pts in colors.values():
        if len(pts) < 2:
            continue

        # Remove points that lie exactly on the segment between two other points.
        def on_segment(a, b, c):
            (ax, ay), (bx, by), (cx, cy) = a, b, c
            if (bx - ax) * (cy - ay) != (by - ay) * (cx - ax):
                return False
            return min(ax, bx) <= cx <= max(ax, bx) and min(ay, by) <= cy <= max(ay, by)

        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(pts) and not changed:
                j = i + 1
                while j < len(pts) and not changed:
                    k = j + 1
                    while k < len(pts) and not changed:
                        if on_segment(pts[i], pts[j], pts[k]):
                            pts.pop(k)
                            changed = True
                    k += 1
                j += 1
            i += 1

        if len(pts) < 2:
            continue

        # Convex hull (Monotone chain).
        pts = sorted(set(pts))
        if len(pts) <= 2:
            hull = pts
        else:
            def cross(o, a, b):
                return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

            lower = []
            for p in pts:
                while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                    lower.pop()
                lower.append(p)

            upper = []
            for p in reversed(pts):
                while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                    upper.pop()
                upper.append(p)

            hull = lower[:-1] + upper[:-1]

        # Draw the convex-hull outline.
        m = len(hull)
        if m < 2:
            continue
        for i in range(m):
            a = hull[i]
            b = hull[(i + 1) % m]
            for (x, y) in bres(a, b):
                if 0 <= x < w and 0 <= y < h:
                    out[y][x] = grid[y][x] if grid[y][x] else colors[a if a == (x, y) else b][0] if False else out[y][x]

        # The loop above is intentionally simple but not the main draw:
        # redraw cleanly using the color associated with this group.
        color = grid[hull[0][1]][hull[0][0]]
        for i in range(m):
            a = hull[i]
            b = hull[(i + 1) % m]
            for (x, y) in bres(a, b):
                if 0 <= x < w and 0 <= y < h:
                    out[y][x] = color

    return out

