    colors = {}
    for y in range(h):
        for x in range(w):
            if grid[y][x] != 0:
                colors.setdefault(grid[y][x], []).append((x, y))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    def bresenham(p1, p2):
        x0, y0 = p1
        x1, y1 = p2
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        cells = []
        while True:
            cells.append((x0, y0))
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy
        return cells

    # Draw convex hull outlines for each color
    for c, pts in colors.items():
        hull = convex_hull(pts)
        n = len(hull)
        if n >= 2:
            for i in range(n):
                for (x, y) in bresenham(hull[i], hull[(i + 1) % n]):
                    if 0 <= x < w and 0 <= y < h:
                        out[y][x] = c

    # Draw vertical lines connecting same-color points in the same column
    for c, pts in colors.items():
        cols = {}
        for (x, y) in pts:
            cols.setdefault(x, []).append(y)
        for x, ys in cols.items():
            if len(ys) >= 2:
                y1, y2 = min(ys), max(ys)
                for y in range(y1, y2 + 1):
                    if 0 <= x < w and 0 <= y < h:
