def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Collect coordinates by color.
    by_color = {}
    for y in range(h):
        for x in range(w):
            v = grid[y][x]
            if v:
                by_color.setdefault(v, []).append((x, y))

    # Bresenham line including both endpoints.
    def line_cells(p, q):
        x0, y0 = p
        x1, y1 = q
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        cells = []
        while True:
            cells.append((x0, y0))
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy
        return cells

    # Draw a straight line if every cell strictly between the endpoints is empty.
    def try_draw(p, q, color):
        cells = line_cells(p, q)
        if not cells:
            return
        for cell in cells[1:-1]:
            x, y = cell
            if grid[y][x] != 0:
                return
        for x, y in cells:
            out[y][x] = color

    # A color forms a 2x2 block if it occupies exactly 4 cells that are the corners.
    def is_2x2_block(pts):
        if len(pts) != 4:
            return False
        xs = {p[0] for p in pts}
        ys = {p[1] for p in pts}
        if len(xs) != 2 or len(ys) != 2:
            return False
        x1, x2 = sorted(xs)
        y1, y2 = sorted(ys)
        return {(x1, y1), (x1, y2), (x2, y1), (x2, y2)} == set(pts)

    # Convex hull using monotone chain.
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    # Draw closed convex-hull outline if all edges are clear.
    def draw_hull_if_clear(pts, color):
        hull = convex_hull(pts)
        if len(hull) < 2:
            return
        edges = [line_cells(hull[i], hull[(i + 1) % len(hull)]) for i in range(len(hull))]
        for cells in edges:
            for x, y in cells[1:-1]:
                if grid[y][x] != 0:
                    return
        for cells in edges:
            for x, y in cells:
                out[y][x] = color

    for color, pts in by_color.items():
        if len(pts) < 2:
            continue

        # If the points are already the four corners of a 2x2 square, fill it.
        if is_2x2_block(pts):
            xs = sorted({p[0] for p in pts})
            ys = sorted({p[1] for p in pts})
            for x in xs:
                for y in ys:
                    out[y][x] = color
            continue

        # If the points make an unobstructed convex polygon outline, draw it.
        draw_hull_if_clear(pts, color)

    # Finally connect every pair of same-colored points whose interior is empty.
    for color, pts in by_color.items():
        m = len(pts)
        for i in range(m):
            for j in range(i + 1, m):
                try_draw(pts[i], pts[j], color)

    return out

import numpy as np
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape
    BG = 8

    # Connected components (4-neighborhood) per color.
    comps_by_color = defaultdict(list)
    seen = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            col = a[r, c]
            if col == BG or seen[r, c]:
                continue
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc] and a[nr, nc] == col:
                        seen[nr, nc] = True
                        stack.append((nr, nc))
            comps_by_color[int(col)].append(cells)

    out = np.full((H, W), BG, dtype=int)

    # Try to find the cross anchor: a 3x3/plus-like layout of four 2-cell arms
    # around a 2x2 empty background hole.  The arms must be separate components.
    for hole_r in range(H - 2):
        for hole_c in range(W - 2):
            # 2x2 hole must be empty background.
            if any(a[hole_r + dr, hole_c + dc] != BG
                   for dr in (0, 1) for dc in (0, 1)):
                continue

            # Candidate arm cells just outside the hole.
            top = [(hole_r - 1, hole_c), (hole_r - 1, hole_c + 1)]
            bottom = [(hole_r + 2, hole_c), (hole_r + 2, hole_c + 1)]
            left = [(hole_r, hole_c - 1), (hole_r + 1, hole_c - 1)]
            right = [(hole_r, hole_c + 2), (hole_r + 1, hole_c + 2)]
            arms = [top, bottom, left, right]

            if not all(0 <= rr < H and 0 <= cc < W
                       for arm in arms for rr, cc in arm):
                continue

            # Determine arm colors.  Each arm must be exactly one non-background color.
            ok = True
            arm_colors = []
            for arm in arms:
                vals = {a[rr, cc] for rr, cc in arm}
                if len(vals) != 1 or vals == {BG}:
                    ok = False
                    break
                arm_colors.append(vals.pop())

            if not ok:
                continue
            if len(set(arm_colors)) != 4:
                continue

            # Each arm must be an entire connected component of that color.
            ok = True
            for arm, col in zip(arms, arm_colors):
                match = False
                for cells in comps_by_color[col]:
                    if sorted(cells) == sorted(arm):
                        match = True
                        break
                if not match:
                    ok = False
                    break
            if not ok:
                continue

            # Valid anchor found.  Move every component of each color to its
            # corresponding side of the central 2x2 hole, keeping the original
            # relative cell shape, and clip to the canvas.
            side_map = {
                arm_colors[0]: (hole_r - 1, hole_c, 0),   # top
                arm_colors[1]: (hole_r + 2, hole_c, 1),   # bottom
                arm_colors[2]: (hole_r, hole_c - 1, 2),   # left
                arm_colors[3]: (hole_r, hole_c + 2, 3),   # right
            }

            for col, comps in comps_by_color.items():
                if col not in side_map:
                    continue
                target_top, target_left, _ = side_map[col]
                for cells in comps:
                    min_r = min(r for r, _ in cells)
                    min_c = min(c for _, c in cells)
                    for rr, cc in cells:
                        nr = target_top + (rr - min_r)
                        nc = target_left + (cc - min_c)
                        if 0 <= nr < H and 0 <= nc < W:
                            out[nr, nc] = col
            return out.tolist()

    # Fallback: return the original grid if no anchor pattern is found.
    return [[int(x) for x in row] for row in a.tolist()]

import numpy as np

BG = 8
ARM_OFFSETS = [(-1, 0), (2, 0), (0, -1), (0, 2)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    def cells_of_color(col):
        return [(r, c) for r in range(h) for c in range(w) if a[r, c] == col]

    def bbox(cells):
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)
        return min_r, max_r, min_c, max_c

    def place_cells(cells, color, origin_r, origin_c):
        min_r, _, min_c, _ = bbox(cells)
        for r, c in cells:
            nr = origin_r + (r - min_r)
            nc = origin_c + (c - min_c)
            if 0 <= nr < h and 0 <= nc < w:
                a[nr, nc] = color

    colors = [c for c in range(1, 10) if (a == c).any()]
    out = a.copy()

    # Find the central 2x2 background hole whose four adjacent arms
    # are exactly two-cell blocks of four distinct colors.
    for hr in range(1, h - 2):
        for hc in range(1, w - 2):
            if any(out[hr + dr, hc + dc] != BG for dr in (0, 1) for dc in (0, 1)):
                continue

            arm_cells = []
            arm_cols = []
            ok = True
            for dr, dc in ARM_OFFSETS:
                cells = [(hr + dr, hc + dc), (hr + dr + 1, hc + dc)]
                vals = [a[r, c] for r, c in cells]
                if vals[0] != vals[1] or vals[0] == BG:
                    ok = False
                    break
                arm_cells.append(cells)
                arm_cols.append(vals[0])

            if not ok or len(set(arm_cols)) != 4:
                continue

            top_r, top_c = hr - 1, hc
            bot_r, bot_c = hr + 2, hc
            left_r, left_c = hr, hc - 1
            right_r, right_c = hr, hc + 2

            # Merge every occurrence of each arm color with that arm side.
            for color, (base_r, base_c), horizontal in zip(
                arm_cols,
                [(top_r, top_c), (bot_r, bot_c), (left_r, left_c), (right_r, right_c)],
                [True, True, False, False],
            ):
                cells = cells_of_color(color)
                if not cells:
                    continue
                if horizontal:
                    place_cells(cells, color, base_r, base_c)
                else:
                    min_r, _, min_c, _ = bbox(cells)
                    for r, c in cells:
                        nr = base_r + (r - min_r)
                        nc = base_c + (c - min_c)
                        if 0 <= nr < h and 0 <= nc < w:
                            a[nr, nc] = color
            return a.astype(int).tolist()

    return a.astype(int).tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Find the horizontal wall: the color appearing in the largest run of
    # consecutive rows where every row is fully filled with that color.
    best_run = []
    wall_color = -1
    for c in range(1, 10):
        rows = np.where(np.all(a == c, axis=1))[0]
        if len(rows) == 0:
            continue
        # split into consecutive runs
        start = rows[0]
        prev = rows[0]
        for r in rows[1:]:
            if r == prev + 1:
                prev = r
            else:
                run = prev - start + 1
                if run > len(best_run):
                    best_run = list(range(start, prev + 1))
                    wall_color = c
                start = r
                prev = r
        run = prev - start + 1
        if run > len(best_run):
            best_run = list(range(start, prev + 1))
            wall_color = c

    # Degenerate fallback.
    if wall_color == -1:
        return a.tolist()

    wall_top, wall_bot = best_run[0], best_run[-1]
    out = a.copy()

    # Connected components (4-connected) of all non-wall, non-background cells.
    used = np.zeros((H, W), dtype=bool)
    objects = []
    for y in range(H):
        for x in range(W):
            v = int(a[y, x])
            if v == 0 or v == wall_color or used[y, x]:
                continue
            mask = (a == v) & ~used
            stack = [(y, x)]
            mask[y, x] = False
            cells = []
            while stack:
                cy, cx = stack.pop()
                cells.append((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < H and 0 <= nx < W and mask[ny, nx]:
                        mask[ny, nx] = False
                        stack.append((ny, nx))
            for yy, xx in cells:
                used[yy, xx] = True
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            top, bot = min(ys), max(ys)
            left, right = min(xs), max(xs)
            objects.append({
                "color": v,
                "cells": cells,
                "top": top,
                "bot": bot,
                "left": left,
                "right": right,
                "h": bot - top + 1,
                "w": right - left + 1,
            })

    # For the supplied tasks there are exactly two anchor objects:
    # one above the wall, one below the wall.
    above = [o for o in objects if o["bot"] < wall_top]
    below = [o for o in objects if o["top"] > wall_bot]

    if not above and not below:
        return out.tolist()

    # Choose the object closest to the wall on each side.
    if above:
        anchor_above = max(above, key=lambda o: o["bot"])
    else:
        anchor_above = None
    if below:
        anchor_below = min(below, key=lambda o: o["top"])
    else:
        anchor_below = None

    # The two anchor objects determine the horizontal placement of the merged
    # tower.  The object from the side closer to the wall is used as the base
    # for the tower's x offset.
    if anchor_above and anchor_below:
        base = anchor_above if (anchor_above["bot"] - wall_top) <= (wall_bot - anchor_below["top"]) else anchor_below
    elif anchor_above:
        base = anchor_above
    else:
        base = anchor_below

    # In the examples, all non-wall objects are merged into a single vertical
    # tower whose horizontal placement follows the anchor object's left edge.
    # The tower is ordered by color value, with smaller colors on top.
    # Consecutive objects overlap by exactly one row.
    objs = sorted(objects, key=lambda o: o["color"])
    total_h = sum(o["h"] for o in objs) - (len(objs) - 1)

    # The tower is placed so that it straddles the wall: the wall rows are
    # covered by the tower if possible, otherwise the tower is placed with its
    # center at the wall center.
    wall_h = wall_bot - wall_top + 1
    if total_h >= wall_h:
        start_y = wall_top - (total_h - wall_h) // 2
    else:
        start_y = wall_top - wall_h // 2
    start_y = max(0, min(start_y, H - total_h))

    # Draw objects from top (smallest color) to bottom (largest color).
    # Where objects overlap, the smaller color is drawn on top.
    y0 = start_y
    for o in objs:
        dy = y0 - o["top"]
        dx = base["left"] - o["left"]
        # Collect cells to draw with this object's color.
        draw = []
        for yy, xx in o["cells"]:
            ny, nx = yy + dy, xx + dx
            if 0 <= ny < H and 0 <= nx < W:
                draw.append((ny, nx, o["color"]))

        # Smaller colors overwrite larger colors, but do not overwrite the
        # solid part of the wall except through holes.
        for ny, nx, color in draw:
            if wall_top <= ny <= wall_bot and out[ny, nx] == wall_color:
                # Only fill actual holes from the input.
                if a[ny, nx] != wall_color:
                    out[ny, nx] = color
            else:
                cur = out[ny, nx]
                if cur == 0 or cur > color:
                    out[ny, nx] = color
        y0 += o["h"] - 1

    # Restore the solid wall body; holes may have been filled by objects.
    for r in range(wall_top, wall_bot + 1):
        for c in range(W):
            if a[r, c] == wall_color:
                out[r, c] = wall_color

    return out.astype(int).tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    H, W = a.shape

    # Find the horizontal wall band: a color that fills consecutive rows.
    wall_color = -1
    wall_top = wall_bot = -1
    best_len = 0
    for c in range(1, 10):
        rows = [r for r in range(H) if np.all(a[r] == c)]
        if not rows:
            continue
        start = prev = rows[0]
        for r in rows[1:] + [rows[-1] + 1]:
            if r != prev + 1:
                if prev - start + 1 > best_len:
                    best_len = prev - start + 1
                    wall_color = c
                    wall_top = start
                    wall_bot = prev
                start = prev = r
            else:
                prev = r

    if wall_color == -1:
        return a.tolist()

    # Extract all non-background, non-wall objects.
    objects = []
    used = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            v = int(a[r, c])
            if v in (0, wall_color) or used[r, c]:
                continue
            mask = (a == v)
            stack = [(r, c)]
            mask[r, c] = False
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and mask[ny, nx]:
                        mask[ny, nx] = False
                        stack.append((ny, nx))
            for y, x in cells:
                used[y, x] = True
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            top, bot = min(ys), max(ys)
            left, right = min(xs), max(xs)
            objects.append({
                'color': v,
                'cells': cells,
                'top': top,
                'bot': bot,
                'left': left,
                'right': right,
                'height': bot - top + 1,
                'width': right - left + 1,
            })

    out = np.zeros((H, W), dtype=int)

    # Objects above the wall form the upper tower.
    # Objects below the wall form the lower tower.
    # The wall itself is unchanged, except that object pixels may fill holes.
    for side in ('above', 'below'):
        if side == 'above':
            group = [o for o in objects if o['bot'] < wall_top]
            # Anchor column: leftmost object in this group.
            if group:
                anchor_left = min(o['left'] for o in group)
                # Vertical placement: highest object becomes topmost.
                # Objects are stacked with one-row overlap between consecutive
                # objects, ordered by increasing color (smaller on top).
                group_sorted = sorted(group, key=lambda o: o['color'])
                y = min(o['top'] for o in group)
                for o in group_sorted:
                    dy = y - o['top']
                    dx = anchor_left - o['left']
                    for yy, xx in o['cells']:
                        ny, nx = yy + dy, xx + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            # Never paint over solid wall; holes are filled.
                            if wall_top <= ny <= wall_bot and out[ny, nx] == wall_color:
                                if a[ny, nx] != wall_color:
                                    out[ny, nx] = o['color']
                            else:
                                cur = out[ny, nx]
                                # Smaller numeric colors overwrite larger ones.
                                if cur == 0 or cur > o['color']:
                                    out[ny, nx] = o['color']
                    y += o['height'] - 1
        else:
            group = [o for o in objects if o['top'] > wall_bot]
            if group:
                anchor_left = min(o['left'] for o in group)
                group_sorted = sorted(group, key=lambda o: o['color'])
                y = min(o['top'] for o in group)
                for o in group_sorted:
                    dy = y - o['top']
                    dx = anchor_left - o['left']
                    for yy, xx in o['cells']:
                        ny, nx = yy + dy, xx + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if wall_top <= ny <= wall_bot and out[ny, nx] == wall_color:
                                if a[ny, nx] != wall_color:
                                    out[ny, nx] = o['color']
                            else:
                                cur = out[ny, nx]
                                if cur == 0 or cur > o['color']:
                                    out[ny, nx] = o['color']
                    y += o['height'] - 1

    # Restore the solid wall body.  Holes in the original wall may have been
    # filled by object pixels; leave those filled.
    for r in range(wall_top, wall_bot + 1):
        for c in range(W):
            if a[r, c] == wall_color:
                out[r, c] = wall_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])

    # The background is the color forming the top-left corner;
    # the foreground is the other color appearing in the pattern.
    bg = grid[0][0]
    fg = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                fg = grid[r][c]
                break
        if fg is not None:
            break

    if fg is None:
        # No pattern; return an empty crop.
        return []

    # Find the bounding box of the foreground color.
    min_r, max_r = h, -1
    min_c, max_c = w, -1
    for r in range(h):
        row = grid[r]
        for c in range(w):
            if row[c] == fg:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # Crop to that bounding box and force its border to be foreground.
    ch = max_r - min_r + 1
    cw = max_c - min_c + 1
    cropped = [[fg if i == 0 or i == ch - 1 or j == 0 or j == cw - 1
                else grid[min_r + i][min_c + j]
                for j in range(cw)]
               for i in range(ch)]

    # Downsample by a factor of 2: keep every second row and column,
    # including the first and last.
    out = []
    for i in range(0, ch, 2):
        out.append([cropped[i][j] for j in range(0, cw, 2)])

    return out

