        return []
    w = len(grid[0])

    out = [row[:] for row in grid]

    # Sources are exactly the cells that are 2 in the input.
    # Upward beam: color 2, stops before the previous input 2 in the same column.
    # Downward beam: color 6, stops before the next input 2 in the same column.
    for c in range(w):
        prev_2 = -1
        for r in range(h):
            if grid[r][c] == 2:
                # upward beam from this 2 to just below the previous input 2
                for rr in range(prev_2 + 1, r):
                    out[rr][c] = 2
                prev_2 = r

        next_2 = h
        for r in range(h - 1, -1, -1):
            if grid[r][c] == 2:
                # downward beam from this 2 to just above the next input 2
                for rr in range(r + 1, next_2):
                    out[rr][c] = 6
                next_2 = r

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components of 2s (8-connected)
    visited = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and not visited[r][c]:
                # BFS
                q = deque([(r, c)])
                visited[r][c] = True
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
                comps.append(cells)

    # For each component, draw the chamfered shell of its bounding box
    for cells in comps:
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)

        corners = [(rmin, cmin), (rmin, cmax), (rmax, cmin), (rmax, cmax)]

        for rr in range(rmin, rmax + 1):
            for cc in range(cmin, cmax + 1):
                # Must be on the border of the bounding box
                if rr != rmin and rr != rmax and cc != cmin and cc != cmax:
                    continue
                # Must be 7 (background) in the original
                if grid[rr][cc] != 7:
                    continue
                # Chamfer: exclude cells within Manhattan distance 3 of any corner
                chamfered = False
                for cr, cc2 in corners:
                    if abs(rr - cr) + abs(cc - cc2) <= 3:
                        chamfered = True
                        break
                if not chamfered:
                    out[rr][cc] = 6

    return out

