    h, w = g.shape

    # The separator is the column of 4s.
    col4 = int(np.where((g == 4).sum(axis=0) == h)[0][0])
    left = g[:, :col4]
    right = g[:, col4 + 1:]

    # Output is the 7-wide region to the right of the separator.
    out = np.zeros((h, 7), dtype=int)

    # Put the 5 at the same row, mapped from right-half coordinates to output coordinates.
    y5, x5 = np.argwhere(right == 5)[0]
    out[int(y5), int(x5) - 1] = 5

    # Find all non-zero 3x3 tiles on the left.
    tiles = []
    for r in range(h - 2):
        for c in range(7 - 2):
            if left[r:r + 3, c:c + 3].max() != 0:
                t = _tile(left, r, c)
                color = next(v for v in t if v != 0)
                tiles.append((int(r), int(c), t, int(color)))

    for r, c, t, color in tiles:
        # Shape is encoded by the positions of zero cells inside the 3x3 tile.
        zeros = tuple((i, j) for i in range(3) for j in range(3) if t[i * 3 + j] == 0)

        if zeros == ((0, 1), (1, 1)):
            dr, dc, L, kind = 0, 1, 2, 'h'       # A
        elif zeros == ((0, 1), (1, 0), (1, 2), (2, 0), (2, 2)):
            dr, dc, L, kind = 1, 0, 2, 'v'       # B
        elif zeros == ((0, 2), (1, 1), (2, 0), (2, 2)):
            dr, dc, L, kind = 0, 1, 3, 'h'       # C
        elif zeros == ((1, 0), (1, 2), (2, 1)):
            dr, dc, L, kind = 0, 1, 4, 'h'       # D
        else:
            continue

        # Output line anchor.
        ar, ac = r + 1, c
        for step in range(1, 13):
            nr, nc = ar + dr * step, ac + dc * step
            if not (0 <= nr < h and 0 <= nc < 7):
                break
            if out[nr, nc] != 0:
                break
            if kind == 'h':
                for k in range(L):
                    out[nr, nc + k] = color
            else:
                for k in range(L):
                    out[nr + k, nc] = color
            break

    return out.tolist()

