    g = _as_grid(grid)
    H, W = g.shape

    # Candidate colors are those appearing in a compact rectangular region.
    # In these puzzles, that is the constant "cover" color, often 8, 9, 2, etc.
    counts = np.bincount(g.ravel(), minlength=10)
