    best = None  # (score, rect)
    for color in colors:
        for rect in _candidate_rects((g == color), max_area=120, min_area=4):
            sc = _score_rect(g, rect, color)
            if best is None or sc > best[0]:
                best = (sc, rect)

    if best is None:
        # Fallback: return 1x1 zero grid (should not happen for intended inputs).
        return [[0]]

    r, c, r2, c2 = best[1]
    H, W = g.shape

    # Determine which full translation best reconstructs the block.
    def full_translation_score(dr, dc):
        h = r2 - r + 1
        w = c2 - c + 1
        nr, nc = r + dr, c + dc
        if nr < 0 or nc < 0 or nr + h > H or nc + w > W:
            return -10**9
