        cover_in_src = int(np.sum((g[nr:nr + h, nc:nc + w] == best[1][0] if False else (g[nr:nr + h, nc:nc + w] == colors[0])))
        # The color in best[1] is a rectangle, not color; fetch actual color separately below.
        return equal * 1000 - cover_in_src * 0.1

    # We need the cover color for the chosen rectangle.
    cover_color = None
    for color in colors:
        if (g[r:r2 + 1, c:c2 + 1] == color).any():
            cover_color = color
            break

    h = r2 - r + 1
    w = c2 - c + 1
    candidates = []
    for dr in range(-H + 1, H):
        for dc in range(-W + 1, W):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if nr < 0 or nc < 0 or nr + h > H or nc + w > W:
                continue
            src = g[r:r2 + 1, c:c2 + 1]
            dst = g[nr:nr + h, nc:nc + w]
            if not np.array_equal(src, dst):
                continue
            # Score reconstruction candidates: prefer source without cover color,
            # and source that itself has a solid-color counterpart (stability).
            cover_in_src = int(np.sum(dst == cover_color))
            score = -cover_in_src * 10
            # Prefer source with more uniform non-cover colors? not necessary.
            # Prefer source farther from target? no.
            # Prefer source whose equal counterpart does not contain cover either.
            for dr2 in range(-H + 1, H):
                for dc2 in range(-W + 1, W):
                    if dr2 == 0 and dc2 == 0:
                        continue
                    rr2, cc2 = nr + dr2, nc + dc2
                    if rr2 < 0 or cc2 < 0 or rr2 + h > H or cc2 + w > W:
                        continue
                    if np.array_equal(g[nr:nr + h, nc:nc + w], g[rr2:rr2 + h, cc2:cc2 + w]):
                        if np.sum(g[rr2:rr2 + h, cc2:cc2 + w] == cover_color) == 0:
                            score += 2
