def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Find bounding box of all zero cells (the canvas)
    zero_rows = np.any(a == 0, axis=1)
    zero_cols = np.any(a == 0, axis=0)
    r1 = int(np.argmax(zero_rows))
    r2 = int(H - 1 - np.argmax(zero_rows[::-1]))
    c1 = int(np.argmax(zero_cols))
    c2 = int(W - 1 - np.argmax(zero_cols[::-1]))

    H_out = r2 - r1 + 1
    W_out = c2 - c1 + 1
    out = np.zeros((H_out, W_out), dtype=int)

    # Legend: non-zero cells in the canvas's column 1
    legend = {}
    for r in range(r1, r2 + 1):
        v = int(a[r, c1 + 1])
        if v != 0:
            legend[v] = r - r1

    # Mask: canvas region is excluded from component counting
    mask = np.zeros((H, W), dtype=bool)
    mask[r1:r2 + 1, c1:c2 + 1] = True

    def count_components_8(color: int) -> int:
        seen = np.zeros((H, W), dtype=bool)
        count = 0
        for i in range(H):
            for j in range(W):
                if mask[i, j] or seen[i, j] or a[i, j] != color:
                    continue
                q = deque([(i, j)])
                seen[i, j] = True
                count += 1
                while q:
                    y, x = q.popleft()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not mask[ny, nx] and not seen[ny, nx] and a[ny, nx] == color:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
        return count

    for color, row in legend.items():
        n = count_components_8(color)
        for k in range(n):
            col = 1 + 2 * k
            if 0 <= row < H_out and 0 <= col < W_out:
                out[row, col] = color

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = np.array(grid, dtype=int)
    h, w = grid.shape

    # Determine background as the most common colour.
    vals, counts = np.unique(grid, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Mask of all non-background pixels.
    nonbg = grid != bg
    if not nonbg.any():
        return []

    # 4-neighbour connected components of the whole foreground.
    comp_id = -np.ones((h, w), dtype=int)
    components = []

    def neighbours(r, c):
        yield r - 1, c
        yield r + 1, c
        yield r, c - 1
        yield r, c + 1

    for r in range(h):
        for c in range(w):
            if nonbg[r, c] and comp_id[r, c] == -1:
                cid = len(components)
                stack = [(r, c)]
                comp_id[r, c] = cid
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for nx, ny in neighbours(x, y):
                        if 0 <= nx < h and 0 <= ny < w:
                            if nonbg[nx, ny] and comp_id[nx, ny] == -1:
                                comp_id[nx, ny] = cid
                                stack.append((nx, ny))
                components.append(cells)

    # Keep the largest foreground component.  If several equally large,
    # choose the one containing the first foreground cell in row-major order.
    first_fg = None
    for r in range(h):
        for c in range(w):
            if nonbg[r, c]:
                first_fg = (r, c)
                break
        if first_fg is not None:
            break

    main_cid = max(
        range(len(components)),
        key=lambda i: (
            len(components[i]),
            -min(min(r, c) for r, c in components[i])
        )
    if first_fg is not None:
        first_cid = comp_id[first_fg[0], first_fg[1]]
        if len(components[first_cid]) == len(components[main_cid]):
            main_cid = first_cid

    cells = components[main_cid]

    # Build adjacency graph inside the main component.
    cell_set = set(cells)
    adj = {cell: [] for cell in cells}
    for (r, c) in cells:
        for nr, nc in neighbours(r, c):
            if (nr, nc) in cell_set:
                adj[(r, c)].append((nr, nc))

    # Find path endpoints: degree 1 if possible, otherwise degree 2.
    endpoints = [cell for cell in cells if len(adj[cell]) == 1]
    if len(endpoints) < 2:
        endpoints = [cell for cell in cells if len(adj[cell]) == 2]

    # If no suitable endpoints (e.g. cycle or singleton), choose a deterministic start.
    if len(endpoints) < 2:
        start = min(cells, key=lambda p: (p[0], p[1]))
    else:
        start = min(endpoints, key=lambda p: (p[0], p[1]))

    # DFS following the foreground path.
    order = [start]
    if len(cells) == 1:
        path = order
    else:
        prev = None
        cur = start
        visited = {start}
        while True:
            nxt = None
            for nb in adj[cur]:
                if nb != prev and nb not in visited:
                    nxt = nb
                    break
            if nxt is None:
                break
            prev, cur = cur, nxt
            visited.add(cur)
            order.append(cur)

    # If DFS did not cover all cells (branching), append remaining cells in a
    # stable row-major order to guarantee full coverage.
    if len(order) != len(cells):
        order_set = set(order)
        for cell in sorted(cells):
            if cell not in order_set:
                order.append(cell)
                order_set.add(cell)

    # Flatten to a 1-column list.
    return [[int(grid[r, c])] for r, c in order]

