def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    colours, counts = np.unique(g, return_counts=True)
    bg = int(colours[np.argmax(counts)])

    fg = g != bg
    if not fg.any():
        return []

    # Connected components of foreground using 4-neighbourhood.
    comp = -np.ones((h, w), dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if fg[r, c] and comp[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp[r, c] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                        if 0 <= nx < h and 0 <= ny < w and fg[nx, ny] and comp[nx, ny] == -1:
                            comp[nx, ny] = cid
                            q.append((nx, ny))
                comps.append(cells)

    # Keep the largest connected foreground component.
    main_cid = max(range(len(comps)), key=lambda i: len(comps[i]))
    cells = comps[main_cid]
    cell_set = set(cells)

    def neighbours(r, c):
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (nr, nc) in cell_set:
                yield nr, nc

    adj = {cell: list(neighbours(*cell)) for cell in cells}

    # Prefer a path endpoint (degree 1); otherwise use the topmost-leftmost cell.
    endpoints = [cell for cell in cells if len(adj[cell]) == 1]
    if endpoints:
        start = min(endpoints, key=lambda p: (p[0], p[1]))
    else:
        start = min(cells, key=lambda p: (p[0], p[1]))

    # Traversal: when there is a branch, choose the unvisited neighbour that is
    # closest to the start; this keeps the output stable and deterministic.
    order = [start]
    visited = {start}

    def dist_to_start(cell):
        # Chebyshev distance, sufficient for deterministic tie-breaking.
        return max(abs(cell[0] - start[0]), abs(cell[1] - start[1]))

    cur = start
    prev = None
    while True:
        cands = []
        for nb in adj[cur]:
            if nb not in visited and nb != prev:
                cands.append(nb)
        if not cands:
            break
        nxt = min(cands, key=lambda p: (dist_to_start(p), p[0], p[1]))
        visited.add(nxt)
        order.append(nxt)
        prev, cur = cur, nxt

    # If traversal did not visit everything (e.g. disconnected leftovers), append
    # the rest deterministically.
    if len(order) != len(cells):
        rem = [cell for cell in cells if cell not in visited]
        rem.sort(key=lambda p: (dist_to_start(p), p[0], p[1]))
        order.extend(rem)

    return [[int(g[r, c])] for r, c in order]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.asarray(grid, dtype=int)
    h, w = g.shape
    out = g.copy()
    seen = np.zeros((h, w), dtype=bool)

    def component(r, c):
        stack = [(r, c)]
        cells = []
        start = g[r, c]
        while stack:
            y, x = stack.pop()
            if y < 0 or y >= h or x < 0 or x >= w:
                continue
            if seen[y, x] or g[y, x] != start:
                continue
            seen[y, x] = True
            cells.append((y, x))
            stack.extend([(y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)])
        return cells

    components = []
    for r in range(h):
        for c in range(w):
            if not seen[r, c]:
                comp = component(r, c)
                if len(comp) >= 2:
                    components.append(comp)

    if not components:
        return out.tolist()

    # Identify the reference color: the smallest color that appears in at least
    # two distinct components.  In all supplied cases this is the common
    # "marker" color used to determine the alignment line.
    ref_color = None
    for color in range(1, 10):
        present = [comp for comp in components
                   if any(g[y, x] == color for y, x in comp)]
        if len(present) >= 2:
            ref_color = color
            break

    if ref_color is None:
        return out.tolist()

    # If every relevant marker is in one row, components are shifted vertically;
    # otherwise they are shifted horizontally.
    marker_rows = [y for comp in components for (y, x) in comp if g[y, x] == ref_color]
    if len(set(marker_rows)) == 1:
        target = marker_rows[0]
        for comp in components:
            marker_cells = [(y, x) for (y, x) in comp if g[y, x] == ref_color]
            if not marker_cells:
                continue
            dy = target - marker_cells[0][0]
            for (y, x) in comp:
                ny = y + dy
                if 0 <= ny < h:
                    out[ny, x] = g[y, x]
        return out.tolist()

    marker_cols = [x for comp in components for (y, x) in comp if g[y, x] == ref_color]
    target = min(marker_cols)
    for comp in components:
        marker_cells = [(y, x) for (y, x) in comp if g[y, x] == ref_color]
        if not marker_cells:
            continue
        dx = target - marker_cells[0][1]
        for (y, x) in comp:
            nx = x + dx
            if 0 <= nx < w:
                out[y, nx] = g[y, x]

    return out.tolist()

