    for r in range(h):
        for c in range(w):
            if visited[r][c] or grid[r][c] == bg:
                continue

            q = deque([(r, c)])
            visited[r][c] = True
            cells = []
            colors = Counter()

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                colors[grid[y][x]] += 1

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny][nx] and grid[ny][nx] != bg:
                            visited[ny][nx] = True
                            q.append((ny, nx))

            comps.append((cells, colors))

    anchor_color = None
    target_r = target_c = None

    # Prefer a singleton component as the global reference/anchor.
    for cells, colors in comps:
        if len(cells) == 1:
            y, x = cells[0]
            anchor_color = grid[y][x]
            target_r, target_c = y, x
            break

    # If no singleton exists, infer the anchor from repeated singleton-colored
    # cells inside larger components.
    if anchor_color is None:
        counts = Counter(
            color
            for cells, colors in comps
            for color, cnt in colors.items()
            if cnt == 1
        )
        if counts:
            anchor_color = counts.most_common(1)[0][0]

    # Find target row/column from singleton components with that anchor color.
    if anchor_color is not None:
        ref_rows, ref_cols = [], []
        for cells, colors in comps:
