import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.asarray(grid, dtype=int)
    h, w = arr.shape

    def is_valid(wide: int, n: int) -> bool:
        if n <= 0:
            return False
        if wide * n + (n - 1) != w:
            return False
        if wide <= 0:
            return False
        # separator columns must be a single non-background colour in every row
        sep_cols = [wide * k + k for k in range(n)]
        for r in range(h):
            vals = {int(arr[r, c]) for c in sep_cols}
            if len(vals) != 1:
                return False
            if vals.pop() == 0:
                return False
        return True

    # Prefer the split with the maximum number of panels, consistent with examples.
    best = None
    for wide in range(1, w + 1):
        n = (w + 1) // (wide + 1)
        if is_valid(wide, n):
            if best is None or n > best[1]:
                best = (wide, n)

    if best is None:
        # Fallback: return the leftmost square/cropped region (should not be needed).
        n = min(h, w)
        return arr[:n, :n].tolist()

    wide, n = best
    sep_color = int(arr[0, 0]) if n > 1 else 0

    panels = []
    for k in range(n):
        start = wide * k + k
        panels.append(arr[:, start:start + wide])

    if n == 1:
        return panels[0].tolist()

    # Remove panels that are uniform.
    active = []
    for p in panels:
        colors = set(p.ravel().tolist())
        if len(colors) > 1:
            active.append(p)

    if not active:
        return [[0] * wide for _ in range(h)]

    if len(active) == 1:
        # Only one informative panel: take it and map the dominant non-background colour
        # to the separator colour if it differs.
        p = active[0].astype(int)
        # background of the input is the most common value in the informative panel
        # unless it is the separator colour, which we preserve as background.
        counts = Counter(p.ravel().tolist())
        bg = counts.most_common(1)[0][0]
        nonbg = {c for c in counts if c != bg}
        if sep_color in nonbg and len(nonbg) == 1:
            fg = nonbg.pop()
            out = np.where(p == fg, sep_color, bg)
            return out.tolist()
        return p.tolist()

    # General rule: keep cells where all informative panels agree on a non-background
    # value; the agreed value is recoloured to the separator colour.
    out = np.full((h, wide), sep_color, dtype=int)
    bg_candidates = []
    for r in range(h):
        for c in range(wide):
            vals = [int(p[r, c]) for p in active]
            if len(set(vals)) == 1:
                v = vals[0]
                # If all panels agree on a value that is not the separator, it is
                # the result feature; recolour it to the separator colour.
                if v != sep_color:
                    out[r, c] = sep_color
                else:
                    out[r, c] = v
            else:
                # Disagreement or mixed panels: output background.
                # In the provided examples this is the separator colour as background.
                out[r, c] = sep_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque
    sys.setrecursionlimit(1000000)

    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    g = [[int(x) for x in row] for row in grid]

    def neighbors4(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < h:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < w:
            yield r, c + 1

    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    yield nr, nc

    # Remove 4-connected components of 1s that have exactly one cell.
    visited = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not visited[r][c]:
                stack = [(r, c)]
                comp = []
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for nr, nc in neighbors4(cr, cc):
                        if not visited[nr][nc] and g[nr][nc] == 1:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                if len(comp) == 1:
                    g[r][c] = 0

    # Recolor 4-connected components of 1s:
    # - if the component has no 0 in its 8-neighborhood, fill it with 7;
    # - otherwise, change every 1 adjacent (8-neighborhood) to a 0 into 7.
    visited = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not visited[r][c]:
                stack = [(r, c)]
                comp = []
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for nr, nc in neighbors4(cr, cc):
                        if not visited[nr][nc] and g[nr][nc] == 1:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                zero_touch = False
                mark = set()
                for cr, cc in comp:
                    for nr, nc in neighbors8(cr, cc):
                        if g[nr][nc] == 0:
                            zero_touch = True
                            break
                    if zero_touch:
                        break

                if not zero_touch:
                    for cr, cc in comp:
                        g[cr][cc] = 7
                else:
                    for cr, cc in comp:
                        for nr, nc in neighbors8(cr, cc):
                            if g[nr][nc] == 0:
                                mark.add((cr, cc))
                                break
                    for cr, cc in mark:
                        g[cr][cc] = 7

    return g

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    g = [[int(x) for x in row] for row in grid]

    def n8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    yield nr, nc

    # Find all 4-connected components of 1s.
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == 1 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
                components.append(comp)

    # A component is a "container" if it completely surrounds at least one 0:
    # all 4-connected components of 0s that touch this component also touch
    # the border.  Equivalently, no touching 0-component can reach border.
    #
    # Build 0-components first for reachability.
    zero_seen = [[False] * w for _ in range(h)]
    zero_id = [[-1] * w for _ in range(h)]
    zero_components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and not zero_seen[r][c]:
                cid = len(zero_components)
                stack = [(r, c)]
                zero_seen[r][c] = True
                comp = []
                touches_border = False
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    if cr == 0 or cr == h - 1 or cc == 0 or cc == w - 1:
                        touches_border = True
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == 0 and not zero_seen[nr][nc]:
                            zero_seen[nr][nc] = True
                            stack.append((nr, nc))
                zero_components.append((comp, touches_border))
                for cr, cc in comp:
                    zero_id[cr][cc] = cid

    # For each 1-component, see which zero-components it touches.
    container = [False] * len(components)
    for idx, comp in enumerate(components):
        touched = set()
        for r, c in comp:
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == 0:
                    touched.add(zero_id[nr][nc])
        # If any touched zero-component does not touch the border, it is enclosed.
        if any((not zero_components[zid][1]) for zid in touched):
            container[idx] = True

    # Mark all 1 cells belonging to container components.
    in_container = [[False] * w for _ in range(h)]
    for idx, comp in enumerate(components):
        if container[idx]:
            for r, c in comp:
                in_container[r][c] = True

    # For every 0 adjacent to a container 1, paint its 8-neighbors with 7,
    # but never overwrite original 0s.
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                continue
            touches_container = False
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and in_container[nr][nc]:
                    touches_container = True
                    break
            if not touches_container:
                continue
            for nr, nc in n8(r, c):
                if g[nr][nc] == 1:
                    g[nr][nc] = 7

    return g

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    orig = [list(row) for row in grid]
    g = [[int(v) for v in row] for row in grid]

    def neighbors4(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
