        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    yield nr, nc

    # Remove isolated 1-pixels (4-connected components of size 1).
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for nr, nc in neighbors4(cr, cc):
