                            seen[nr][nc] = True
                            stack.append((nr, nc))
                if len(comp) == 1:
                    g[r][c] = 0

    # Mark cells that must stay 0: original 0s plus removed isolated 1s.
    keep_zero = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if orig[r][c] == 0 or g[r][c] == 0:
                keep_zero[r][c] = True

    out = [row[:] for row in g]

    # For every original 0 that is 4-adjacent to a surviving 1,
    # paint its 8-neighbors with 7 unless they must stay 0.
    for r in range(h):
        for c in range(w):
            if orig[r][c] != 0:
                continue
            has_surviving_1_neighbor = False
            for nr, nc in neighbors4(r, c):
                if g[nr][nc] == 1:
                    has_surviving_1_neighbor = True
                    break
            if not has_surviving_1_neighbor:
                continue
            for nr, nc in neighbors8(r, c):
                if not keep_zero[nr][nc] and out[nr][nc] == 1:
                    out[nr][nc] = 7

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    out = [list(row) for row in grid]

    # Find all 4-connected components of 0s
    visited = [[False] * w for _ in range(h)]
    enclosed_zero_cells = []

    for r in range(h):
        for c in range(w):
            if out[r][c] == 0 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                comp = []
                touches_border = False
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    if cr == 0 or cr == h - 1 or cc == 0 or cc == w - 1:
                        touches_border = True
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 0 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                if not touches_border:
                    enclosed_zero_cells.extend(comp)

    # For each enclosed 0-cell, paint its 8-neighborhood 1s to 7
    for r, c in enclosed_zero_cells:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 1:
                    out[nr][nc] = 7

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    h, w = g.shape
    bh, bw = h // 3, w // 3

    # background is the most frequent color overall
    bg = Counter(g.ravel()).most_common(1)[0][0]

    # determine separator width:
    # a separator row/column is one that is completely background
    def is_blank_row(i):
        return all(g[i, j] == bg for j in range(w))

    def is_blank_col(j):
        return all(g[i, j] == bg for i in range(h))

    sep = 1
    for k in range(0, bh):
        if is_blank_row(k) and is_blank_col(k):
            sep = k
            break

    # extract the single non-background pixel of each 10x10 block
    pixels = []
    for bi in range(3):
        for bj in range(3):
            block = g[bi * bh:(bi + 1) * bh, bj * bw:(bj + 1) * bw]
            mask = block != bg
            if mask.any():
                vals = block[mask]
                # normally exactly one non-background pixel
                px = int(Counter(vals.tolist()).most_common(1)[0][0])
            else:
                px = bg
            pixels.append(px)

    size = 3 * 3 + 2 * sep
    out = np.full((size, size), bg, dtype=int)

    for bi in range(3):
        for bj in range(3):
            r = bi * (3 + sep) + 1
            c = bj * (3 + sep) + 1
            out[r, c] = pixels[bi * 3 + bj]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    h = len(grid)
    w = len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]

    # ---- Connected component labeling (4-connected) ----
    def components(mask, H, W):
        comp = [[-1] * W for _ in range(H)]
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r][c] and comp[r][c] == -1:
                    cells = []
                    stack = [(r, c)]
                    comp[r][c] = len(comps)
                    while stack:
                        a, b = stack.pop()
                        cells.append((a, b))
                        for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            na, nb = a + da, b + db
                            if 0 <= na < H and 0 <= nb < W and comp[na][nb] == -1 and mask[na][nb]:
                                comp[na][nb] = len(comps)
                                stack.append((na, nb))
                    comps.append(cells)
        return comp, comps

    # ---- Find the large MAP block (the biggest solid-color component) ----
    map_comp = -1
    map_size = 0
    map_color = bg
    map_cells = []
    for color in [c for c in range(10) if c != bg]:
        mask = [[grid[r][c] == color for c in range(w)] for r in range(h)]
        comp, comps = components(mask, h, w)
        for i, cells in enumerate(comps):
            if len(cells) > map_size:
                map_size = len(cells)
                map_color = color
                map_cells = cells
                map_comp = i

    rows = [r for r, c in map_cells]
    cols = [c for r, c in map_cells]
    mr0, mr1 = min(rows), max(rows)
    mc0, mc1 = min(cols), max(cols)
    MH = mr1 - mr0 + 1
    MW = mc1 - mc0 + 1
    # map mask (1 = where block is present)
    map_mask = [[0] * MW for _ in range(MH)]
    for (r, c) in map_cells:
        map_mask[r - mr0][c - mc0] = 1

    # ---- Read the map as a 3x3 grid of cells ----
    ch = MH // 3
    cw = MW // 3
    map_grid = []
    for i in range(3):
        rowvals = []
        for j in range(3):
            cnt = 0
            for r in range(i * ch, (i + 1) * ch):
                for c in range(j * cw, (j + 1) * cw):
                    if r < MH and c < MW and map_mask[r][c]:
                        cnt += 1
            rowvals.append(cnt)
        map_grid.append(rowvals)

    # ---- Find the 9 SOURCE objects ----
    def obj_shape(cells, color):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        hgt = max(rs) - min(rs) + 1
        wid = max(cs) - min(cs) + 1
        if hgt == 2 and wid == 2:
            return 'sq22'
        if hgt == 2 and wid == 1:
            return 'v21'
        if hgt == 1 and wid == 2:
            return 'h12'
        if hgt == 3 and wid == 3:
            # cross: 5 pixels with center
            return 'cross33'
        return 'sq22'  # fallback

    sources = []  # (color, shape, area)
    for color in [c for c in range(10) if c != bg and c != map_color]:
        mask = [[grid[r][c] == color for c in range(w)] for r in range(h)]
        comp, comps = components(mask, h, w)
        for cells in comps:
            if len(cells) >= 2:
                sources.append((color, obj_shape(cells, color), len(cells)))

    # dominant color = most frequent among sources (the one appearing 3x)
    color_counts = Counter(s[0] for s in sources)
    dom_color = color_counts.most_common(1)[0][0]

    # ---- Determine source identity for each map cell value ----
    # map cell values: dom_color -> dominant obj; else -> that color's source
    def source_for(val):
        if val == dom_color:
            for s in sources:
                if s[0] == dom_color:
                    return s
        # else find source with that color
        for s in sources:
            if s[0] == val:
                return s
        return None

    # ---- Determine output size from the 9 objects ----
    def shape_dims(shape):
        if shape == 'sq22':
            return (2, 2)
        if shape == 'v21':
            return (2, 1)
        if shape == 'h12':
            return (1, 2)
        if shape == 'cross33':
            return (3, 3)
        return (2, 2)

    nine = []
    for i in range(3):
        for j in range(3):
            nine.append(source_for(map_grid[i][j]))
    nine = [n for n in nine if n is not None]

    max_h = max(shape_dims(n[1])[0] for n in nine)
    max_w = max(shape_dims(n[1])[1] for n in nine)
    N = max_h + max_w + 2

    # ---- Build output ----
    out = [[map_color] * N for _ in range(N)]

    def draw(shape, color, r0, c0):
        if shape == 'sq22':
            out[r0][c0] = color; out[r0][c0 + 1] = color
            out[r0 + 1][c0] = color; out[r0 + 1][c0 + 1] = color
        elif shape == 'v21':
            out[r0][c0] = color
            out[r0 + 1][c0] = color
        elif shape == 'h12':
            out[r0][c0] = color
            out[r0][c0 + 1] = color
        elif shape == 'cross33':
            out[r0 + 1][c0] = color
            out[r0][c0 + 1] = color
            out[r0 + 1][c0 + 1] = color
            out[r0 + 2][c0 + 1] = color
            out[r0 + 1][c0 + 2] = color

    idx = 0
    for i in range(3):
        for j in range(3):
            n = source_for(map_grid[i][j])
            if n is None:
                continue
            color, shape, _ = n
            ah, aw = shape_dims(shape)
            # center shape within (max_h x max_w) cell
            off_r = (max_h - ah) // 2
            off_c = (max_w - aw) // 2
            r0 = 1 + i * (max_h + 1) + off_r
            c0 = 1 + j * (max_w + 1) + off_c
            draw(shape, color, r0, c0)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    bg = int(Counter(g.ravel()).most_common(1)[0][0])

    def bfs(r0, c0, target):
        seen = set()
        stack = [(r0, c0)]
        seen.add((r0, c0))
        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and g[nr,nc] == target:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return seen

    # Find the largest connected component (the map)
    best_color = -1
    best_cells = set()
    for color in range(10):
        if color == bg:
            continue
        mask = (g == color)
        visited = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for c in range(w):
                if mask[r,c] and not visited[r,c]:
                    cells = bfs(r, c, color)
                    for cell in cells:
                        visited[cell] = True
                    if len(cells) > len(best_cells):
                        best_cells = cells
                        best_color = color

    mr0 = min(r for r,c in best_cells)
    mr1 = max(r for r,c in best_cells)
    mc0 = min(c for r,c in best_cells)
    mc1 = max(c for r,c in best_cells)
    MH = mr1 - mr0 + 1
    MW = mc1 - mc0 + 1

    # Map mask
    map_mask = [[0]*MW for _ in range(MH)]
    for (r,c) in best_cells:
        map_mask[r-mr0][c-mc0] = 1

    # Read map as 3x3 cells
    ch = MH // 3
    cw = MW // 3
    map_grid = []
    for i in range(3):
        rowvals = []
        for j in range(3):
            vals = []
            for r in range(i*ch, (i+1)*ch):
                for c in range(j*cw, (j+1)*cw):
                    if r < MH and c < MW and map_mask[r][c]:
                        vals.append(g[mr0+r, mc0+c])
            if vals:
                rowvals.append(int(Counter(vals).most_common(1)[0][0]))
            else:
                rowvals.append(bg)
        map_grid.append(rowvals)

    # Find source shapes (all components except map color and bg)
    sources = []
    for color in range(10):
        if color == bg or color == best_color:
            continue
        mask = (g == color)
        visited = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for c in range(w):
                if mask[r,c] and not visited[r,c]:
                    cells = bfs(r, c, color)
                    for cell in cells:
                        visited[cell] = True
                    if len(cells) >= 2:
                        rs = [r for r,c in cells]
                        cs = [c for r,c in cells]
                        sh = max(rs)-min(rs)+1
                        sw = max(cs)-min(cs)+1
                        # Create shape array
                        arr = np.zeros((sh, sw), dtype=int)
                        for (r,c) in cells:
                            arr[r-min(rs), c-min(cs)] = color
                        sources.append((color, sh, sw, arr, len(cells)))

    # Dominant color = most frequent source color
    color_counts = Counter(s[0] for s in sources)
    dom_color = color_counts.most_common(1)[0][0]

    # Find source by color (first match)
    def find_source(color):
        for s in sources:
            if s[0] == color:
                return s
        return None

    # Determine the 9 shapes for the output
    nine_shapes = []
    for i in range(3):
        for j in range(3):
            val = map_grid[i][j]
            if val == bg:
                src = find_source(dom_color)
            else:
                src = find_source(val)
            if src is not None:
                nine_shapes.append(src)
            else:
                nine_shapes.append(None)

    # Compute output size
    max_h = max(s[1] for s in nine_shapes if s is not None)
    max_w = max(s[2] for s in nine_shapes if s is not None)
    N = max_h + max_w + 2

    # Output background = map color
    out = np.full((N, N), best_color, dtype=int)

    # Place shapes
    for idx, src in enumerate(nine_shapes):
        if src is None:
            continue
        color, sh, sw, arr, area = src
        bi = idx // 3
        bj = idx % 3
        # Center shape in its cell
        off_r = (max_h - sh) // 2
        off_c = (max_w - sw) // 2
        r0 = 1 + bi * (max_h + 1) + off_r
        c0 = 1 + bj * (max_w + 1) + off_c
        for i in range(sh):
            for j in range(sw):
                if arr[i, j] != 0:
                    if r0+i < N and c0+j < N:
                        out[r0+i, c0+j] = arr[i, j]

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    bg = 8
    out = np.full((H, W), bg, dtype=int)

    # Connected components of 1s and 3s
    comp = np.zeros((H, W), dtype=int)
    shapes = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and comp[r, c] == 0:
                idx = len(shapes) + 1
                q = deque([(r, c)])
                comp[r, c] = idx
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 1, 0, 0):
                        for dx in (0, 0, -1, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W and comp[ny, nx] == 0 and g[ny, nx] in (1, 3):
                                comp[ny, nx] = idx
                                q.append((ny, nx))
                ys = [y for y, x in cells]
                xs = [x for y, x in cells]
                rows = list(range(min(ys), max(ys) + 1))
                cols = list(range(min(xs), max(xs) + 1))
                # directions where 3 touches the shape boundary
                dirs = []
                if min(ys) > 0 and all(g[min(ys) - 1, c] != 3 for c in cols) and any(g[min(ys) - 1, c] == 3 for c in cols):
                    dirs.append((0, -1))
                if max(ys) < H - 1 and any(g[max(ys) + 1, c] == 3 for c in cols):
                    dirs.append((0, 1))
                if min(xs) > 0 and any(g[r, min(xs) - 1] == 3 for r in rows):
                    dirs.append((-1, 0))
                if max(xs) < W - 1 and any(g[r, max(xs) + 1] == 3 for r in rows):
                    dirs.append((1, 0))
                shapes.append({"rows": rows, "cols": cols, "cells": cells, "dirs": dirs})

    # Marker: 4 with vertical 2s below it. Direction is up.
    markers = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 4:
                markers.append((r, c, (0, -1)))

    # Expand every shape to its bounding box in color 2
    for sh in shapes:
        out[sh["rows"][0]:sh["rows"][-1] + 1, sh["cols"][0]:sh["cols"][-1] + 1] = 2

    def shoot(sr, sc, dr, dc):
        """Draw a 2-beam from (sr, sc) in direction (dr, dc), stopping before first 1/3 cell."""
        r, c = sr, dc  # intentional? no
        r, c = sr, sc
        while 0 <= r < H and 0 <= c < W:
            if g[r, c] in (1, 3):
                break
            out[r, c] = 2
            r += dr
            c += dc

    # Beams from 3-side extensions of shapes, starting at boundary cell
    for sh in shapes:
        rows = sh["rows"]
        cols = sh["cols"]
        if (0, -1) in sh["dirs"]:
            for c in cols:
                shoot(rows[0] - 1, c, 0, -1)
        if (0, 1) in sh["dirs"]:
            for c in cols:
                shoot(rows[-1] + 1, c, 0, 1)
        if (-1, 0) in sh["dirs"]:
            for r in rows:
                shoot(r, cols[0] - 1, -1, 0)
        if (1, 0) in sh["dirs"]:
            for r in rows:
                shoot(r, cols[-1] + 1, 1, 0)

    # Beam from the 4 marker, starting just above the 4
    for mr, mc, (dr, dc) in markers:
        shoot(mr + dr, mc + dc, dr, dc)

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Connected components made of 1s and 3s.
    comp = np.zeros((H, W), dtype=int)
    shapes = []

    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and comp[r, c] == 0:
                idx = len(shapes) + 1
                q = deque([(r, c)])
                comp[r, c] = idx
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and comp[ny, nx] == 0 and g[ny, nx] in (1, 3):
                            comp[ny, nx] = idx
                            q.append((ny, nx))

                ones = [(y, x) for y, x in cells if g[y, x] == 1]
                threes = [(y, x) for y, x in cells if g[y, x] == 3]

                ys = [y for y, _ in ones]
                xs = [x for _, x in ones]
                top, bottom = min(ys), max(ys)
                left, right = min(xs), max(xs)
                height = bottom - top + 1
                width = right - left + 1
                midr = (top + bottom) // 2
                midc = (left + right) // 2

                dirv = None
                if threes:
                    t_ys = [y for y, _ in threes]
                    t_xs = [x for _, x in threes]
                    t_top, t_bottom = min(t_ys), max(t_ys)
                    t_left, t_right = min(t_xs), max(t_xs)
                    if t_bottom < top:
                        dirv = (-1, 0)
                    elif t_top > bottom:
                        dirv = (1, 0)
                    elif t_left < left:
                        dirv = (0, -1)
                    elif t_right > right:
                        dirv = (0, 1)

                shapes.append((top, bottom, left, right, height, width, midr, midc, dirv, threes))

    # The 4 with 2s below is the target column.
    target_col = None
    for r in range(H):
        for c in range(W):
            if g[r, c] == 4:
                target_col = c
                break
        if target_col is not None:
            break

    # For shapes whose 3-side points toward the target column, paint the
    # axis-aligned rectangle from the shape's 3-side to the target column.
    for (top, bottom, left, right, height, width, midr, midc, dirv, threes) in shapes:
        if dirv == (0, -1) and target_col is not None and target_col < left:
            out[midr, target_col:left] = 2
        elif dirv == (0, 1) and target_col is not None and target_col > right:
            out[midr, right + 1:target_col + 1] = 2

    # The 4/2 marker becomes a full vertical 2-line in its column.
    if target_col is not None:
        out[:, target_col] = 2

    return out.tolist()

import numpy as np
from collections import deque

def _components(mask, rows, cols):
    seen = np.zeros((rows, cols), dtype=bool)
    comps = []
    for r in range(rows):
        for c in range(cols):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if mask[nr, nc] and not seen[nr, nc]:
                                    seen[nr, nc] = True
                                    q.append((nr, nc))
                comps.append(cells)
    return comps

def _fit(cells, rows, cols, bg):
    best = None
    max_area = max(len(x) for x in (cells,))
    for dr in range(-rows, rows + 1):
        for dc in range(-cols, cols + 1):
            ok = True
            for r, c in cells:
                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                    ok = False
                    break
                if best is not None and (best[0] == 0 or dr != 0 or dc != 0):
                    pass
            if not ok:
                continue
            area = sum(1 for r, c in cells if 0 <= r + dr < rows and 0 <= c + dc < cols)
            if area != len(cells):
                continue
            if best is None or area > best[1] or (area == best[1] and (abs(dr) + abs(dc)) < (abs(best[0][0]) + abs(best[0][1]))):
                best = (((dr, dc), area, (dr, dc)))
    if best is None:
        return None
    return best[0]

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [[int(x) for x in row] for row in grid]
    a = np.array(grid, dtype=int)
    rows, cols = a.shape

    bg = int(np.bincount(a.ravel()).argmax())

    # Determine a consistent vertical translation for each color.
    # For every color, all components must be translated by the same dy.
    # Search dy that lets the whole color set be shifted vertically without leaving the grid.
    colors = sorted({int(v) for v in a.ravel() if int(v) != bg})

    valid_dy = set(range(-rows, rows + 1))
    for col in colors:
        mask = (a == col)
        comps = _components(mask, rows, cols)
        col_ok = set(range(-rows, rows + 1))
        for cells in comps:
            min_r = min(r for r, _ in cells)
            max_r = max(r for r, _ in cells)
            # dy must keep min_r+dy >= 0 and max_r+dy < rows
            lo = -min_r
            hi = rows - 1 - max_r
            allowed = set(range(lo, hi + 1))
            col_ok &= allowed
        valid_dy &= col_ok

    if not valid_dy:
        dy = 0
    else:
