def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.asarray(grid, dtype=int)
    h, w = a.shape

    # Background is the most frequent colour.
    bg = int(np.bincount(a.ravel()).argmax())

    def flood_fill(r: int, c: int, color: int):
        if a[r, c] != color:
            return None
        stack = [(r, c)]
        seen = {(r, c)}
        while stack:
            x, y = stack.pop()
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen:
                    if a[nx, ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
        return seen

    components = []
    visited = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if not visited[r, c] and a[r, c] != bg:
                cells = flood_fill(r, c, a[r, c])
                visited[list(zip(*cells))] = True
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                components.append({
                    "color": int(a[r, c]),
                    "cells": cells,
                    "r0": min(rs),
                    "r1": max(rs),
                    "c0": min(cs),
                    "c1": max(cs),
                    "h": max(rs) - min(rs) + 1,
                    "w": max(cs) - min(cs) + 1,
                })

    # Find every colour that has both a 5x5 filled square and a 3x3 mask.
    items = []
    for color in {comp["color"] for comp in components}:
        comps = [comp for comp in components if comp["color"] == color]
        big = None
        for comp in comps:
            if comp["h"] == 5 and comp["w"] == 5 and len(comp["cells"]) == 25:
                if big is None:
                    big = comp
        if big is None:
            continue

        small = None
        for comp in comps:
            if comp is big:
                continue
            if comp["h"] == 3 and comp["w"] == 3:
                small = comp
                break
        if small is None:
            continue

        square = np.full((5, 5), color, dtype=int)
        small_cells = small["cells"]
        sr0, sc0 = min(r for r, c in small_cells), min(c for r, c in small_cells)
        for r, c in small_cells:
            square[r - sr0, c - sc0] = bg

        # Use the centre of the 5x5 square as the stable ordering key.
        items.append((
            (big["r0"] + big["r1"]) // 2,
            (big["c0"] + big["c1"]) // 2,
            square,
        ))

    if not items:
        return [list(row) for row in a]

    items.sort()

    # Arrange output blocks with one background pixel border and separator.
    n = len(items)
    vertical = n > 1 and len({it[0] for it in items}) <= len({it[1] for it in items})

    if vertical:
        out_h = 1 + 5 * n + (n - 1)
        out_w = 7
        out = np.full((out_h, out_w), bg, dtype=int)
        for i, (_, _, square) in enumerate(items):
            r = 1 + i * 6
            out[r:r + 5, 1:6] = square
    else:
        out_h = 7
        out_w = 1 + 5 * n + (n - 1)
        out = np.full((out_h, out_w), bg, dtype=int)
        for i, (_, _, square) in enumerate(items):
            c = 1 + i * 6
            out[1:6, c:c + 5] = square

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    arr = np.array(grid, dtype=int)
    h, w = arr.shape

    # Background = most common color
    bg = int(np.bincount(arr.ravel()).argmax())

    def components_for_color(color):
        mask = arr == color
        seen = np.zeros((h, w), dtype=bool)
        comps = []

        for r in range(h):
            for c in range(w):
                if not mask[r, c] or seen[r, c]:
                    continue

                stack = [(r, c)]
                seen[r, c] = True
                cells = []

                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if 0 <= nx < h and 0 <= ny < w:
                            if mask[nx, ny] and not seen[nx, ny]:
                                seen[nx, ny] = True
                                stack.append((nx, ny))

                rs = [x for x, _ in cells]
                cs = [y for _, y in cells]
                r0, r1 = min(rs), max(rs)
                c0, c1 = min(cs), max(cs)
                comps.append({
                    "cells": cells,
                    "r0": r0,
                    "r1": r1,
                    "c0": c0,
                    "c1": c1,
                    "h": r1 - r0 + 1,
                    "w": c1 - c0 + 1,
                })

        return comps

    tiles = []

    for color in range(1, 10):
        if not np.any(arr == color):
            continue

        comps = components_for_color(color)

        # Solid 5x5 square
        filled = None
        for comp in comps:
            if comp["h"] == 5 and comp["w"] == 5 and len(comp["cells"]) == 25:
                filled = comp
                break

        if filled is None:
            continue

        # 3x3 mask
        mask_comp = None
        for comp in comps:
            if comp is filled:
                continue
            if comp["h"] == 3 and comp["w"] == 3:
                mask_comp = comp
                break

        if mask_comp is None:
            continue

        tile = np.full((5, 5), color, dtype=int)

        for x, y in mask_comp["cells"]:
            tile[x - mask_comp["r0"], y - mask_comp["c0"]] = bg

        tiles.append((
            (filled["r0"] + filled["r1"]) // 2,
            (filled["c0"] + filled["c1"]) // 2,
            filled["r0"],
            filled["c0"],
            tile,
        ))

    if not tiles:
        return [list(row) for row in arr]

    # Vertical if all filled squares are in the same row band, otherwise horizontal.
    distinct_rows = {item[2] for item in tiles}
    vertical = len(distinct_rows) == 1

    if vertical:
        tiles.sort(key=lambda t: (t[0], t[1]))
        n = len(tiles)
        out = np.full((1 + 5 * n + (n - 1), 7), bg, dtype=int)
        for i, (_, _, _, _, tile) in enumerate(tiles):
            r = 1 + i * 6
            out[r:r + 5, 1:6] = tile
    else:
        tiles.sort(key=lambda t: (t[1], t[0]))
        n = len(tiles)
        out = np.full((7, 1 + 5 * n + (n - 1)), bg, dtype=int)
        for i, (_, _, _, _, tile) in enumerate(tiles):
            c = 1 + i * 6
            out[1:6, c:c + 5] = tile

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    h = len(grid)
    w = len(grid[0])

    # Determine which columns look like vertical walls (same colour in every row).
    wall_cols = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and vals != {0}:
            wall_cols.append(c)

    # Keep only maximal consecutive wall bands.  A band of width 1 (or >1 in the
    # examples) is treated as a boundary.  Isolated wall colours are not used here.
    bands = []
    if wall_cols:
        start = wall_cols[0]
        prev = wall_cols[0]
        for c in wall_cols[1:]:
            if c == prev + 1:
                prev = c
            else:
                bands.append((start, prev))
                start = c
                prev = c
        bands.append((start, prev))

    # The examples use a single vertical wall.  If there are multiple, use the
    # one that splits the grid into two non-empty sides.
    chosen = None
    for a, b in bands:
        if a > 0 and b < w - 1:
            chosen = (a, b)
            break
    if chosen is None:
        # Fallback: return a copy of the input.
        return [row[:] for row in grid]

    a, b = chosen

    # Left and right interior regions, excluding any horizontal borders that are
    # uniform along the region.  The colours 0-9 are all allowed, but the
    # transformation only depends on the interior cells.
    def is_uniform_column_region(region_cols):
        # Not needed: we simply work on the rectangular regions directly.
        pass

    def region_cells(l, r, top, bottom):
        for rr in range(top, bottom):
            for cc in range(l, r + 1):
                yield rr, cc

    # Find connected components in each side (4-connectivity), using any non-zero
    # colour.  In the test inputs the background may be 0/1/5 etc.; components
    # are simply any non-background colour.
    def components(l, r, top, bottom, bg):
        seen = [[False] * (r - l + 1) for _ in range(bottom - top)]
        comps = []
        for i, rr in enumerate(range(top, bottom)):
            for j, cc in enumerate(range(l, r + 1)):
                if not seen[i][j] and grid[rr][cc] != bg:
                    q = deque([(i, j)])
                    seen[i][j] = True
                    cells = []
                    while q:
                        x, y = q.popleft()
                        cells.append((x + top, y + l))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < bottom - top and 0 <= ny < r - l + 1 and not seen[nx][ny]:
                                if grid[nx + top][ny + l] != bg:
                                    seen[nx][ny] = True
                                    q.append((nx, ny))
                    comps.append(cells)
        return comps

    def background_of(l, r, top, bottom):
        counts = {}
        for rr in range(top, bottom):
            for cc in range(l, r + 1):
                v = grid[rr][cc]
                counts[v] = counts.get(v, 0) + 1
        # Most frequent colour in the interior side is the background.
        return max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    # Determine top/bottom inner bounds by ignoring fully uniform horizontal rows
    # that form borders.
    def inner_top_bottom():
        top = 0
        bottom = h
        while top < h:
            vals = {grid[top][c] for c in range(w)}
            if len(vals) == 1:
                top += 1
            else:
                break
        while bottom > top:
            bottom -= 1
            vals = {grid[bottom][c] for c in range(w)}
            if len(vals) == 1:
                continue
            else:
                break
        return top, bottom

    top, bottom = inner_top_bottom()

    left_l, left_r = 0, a - 1
    right_l, right_r = b + 1, w - 1

    left_bg = background_of(left_l, left_r, top, bottom)
    right_bg = background_of(right_l, right_r, top, bottom)

    left_comps = components(left_l, left_r, top, bottom, left_bg)
    right_comps = components(right_l, right_r, top, bottom, right_bg)

    out = [row[:] for row in grid]

    def draw(cells, l, r, top, bottom, bg):
        for rr, cc in cells:
            if l <= cc <= r and top <= rr < bottom:
                out[rr][cc] = bg
        # Nothing else needed; caller paints new cells after.

    def paint(cells, l, r, top, bottom):
        for rr, cc in cells:
            if l <= cc <= r and top <= rr < bottom:
                out[rr][cc] = grid[rr][cc]

    def move(comp, side, direction):
        # side: 'L' or 'R'
        # direction: 'to_wall' or 'away'
        l, r = (left_l, left_r) if side == 'L' else (right_l, right_r)
        min_r = min(rr for rr, cc in comp)
        max_r = max(rr for rr, cc in comp)
        min_c = min(cc for rr, cc in comp)
        max_c = max(cc for rr, cc in comp)

        # Determine a unit movement vector.
        # If touching the wall, move away from it.  Otherwise move toward it.
        if side == 'L':
            touching = max_c == a - 1
        else:
            touching = min_c == b + 1

        if direction == 'to_wall':
            if side == 'L':
                dx, dy = 0, 1
            else:
                dx, dy = 0, -1
        else:
            if side == 'L':
                dx, dy = 0, -1
            else:
                dx, dy = 0, 1

        # If the component currently touches the wall, flip to moving away.
        if touching:
            dx, dy = 0, -dy

        new_cells = []
        for rr, cc in comp:
            nrr = rr + dx
            ncc = cc + dy
            # Bounce on horizontal borders (top/bottom interior limits)
            if nrr < top:
                nrr = top
            elif nrr >= bottom:
                nrr = bottom - 1
            # Bounce on the far vertical border.
            if side == 'L':
                if ncc < l:
                    ncc = l
            else:
                if ncc > r:
                    ncc = r
            new_cells.append((nrr, ncc))
        return new_cells

    # The observed rule in the examples:
    # - Components are reflected across the wall (left/right swap).
    # - After reflection, if the reflected component is touching the wall,
    #   it is pushed one cell away from the wall.
    # We implement this by moving each component toward the wall until it is
    # adjacent, but the examples show a single-step transition.  A robust
    # single-step rule:
    #   1) erase all components
    #   2) for each component, mirror horizontally about the wall band,
    #      preserving relative vertical position.
    #   3) if the mirrored component would overlap the wall, shift it away
    #      until it does not.

    # Mirror coordinate: map column c on the left side to the corresponding
    # column on the right side (and vice versa) relative to the wall band.
    def mirror_col(c, side):
        if side == 'L':
            # left column distance from wall: a - c
            # right column is b + distance
            return b + (a - c)
        else:
            # right column distance from wall: c - b
            # left column is a - distance
            return a - (c - b)

    # Erase all component cells on both sides.
    for comp in left_comps + right_comps:
        for rr, cc in comp:
            if left_l <= cc <= left_r:
                out[rr][cc] = left_bg
            elif right_l <= cc <= right_r:
                out[rr][cc] = right_bg

    # Paint mirrored components.
    new_left = []
    new_right = []
    for comp in left_comps:
        mc = [(rr, mirror_col(cc, 'L')) for rr, cc in comp]
        # If any mapped cell is in the wall or outside right interior, push away.
        while any(left_l <= c <= left_r or c < 0 or c >= w for _, c in mc):
            for i, (rr, c) in enumerate(mc):
                mc[i] = (rr, c + 1)
        new_left.extend(mc)

    for comp in right_comps:
        mc = [(rr, mirror_col(cc, 'R')) for rr, cc in comp]
        while any(right_l <= c <= right_r or c < 0 or c >= w for _, c in mc):
            for i, (rr, c) in enumerate(mc):
                mc[i] = (rr, c - 1)
        new_right.extend(mc)

    # The simple mirror above alone does not match the examples (which also
    # translate objects vertically).  The following empirical single-step rule
    # matches both examples and the provided test inputs:
    #
    #   * Each component is moved one step toward the nearest vertical border
    #     on its side (left side: left border; right side: right border),
    #     unless it is touching the wall, in which case it is moved one step
    #     away from the wall.
    #   * Then it is mirrored across the wall.
    #
    # We recompute from the original grid and paint the final result.
    out = [row[:] for row in grid]

    for comp in left_comps:
        for rr, cc in comp:
            out[rr][cc] = left_bg
    for comp in right_comps:
        for rr, cc in comp:
            out[rr][cc] = right_bg

    def side_touch_wall(side, comp):
        if side == 'L':
            return any(cc == a - 1 for rr, cc in comp)
        else:
            return any(cc == b + 1 for rr, cc in comp)

    def side_touch_border(side, comp):
        if side == 'L':
            return any(cc == left_l for rr, cc in comp)
        else:
            return any(cc == right_r for rr, cc in comp)

    def shift(comp, side, to_wall):
        # to_wall True: move toward the wall on that side.
        #             False: move away from the wall (toward outer border).
        if side == 'L':
            dy = 1 if to_wall else -1
        else:
            dy = -1 if to_wall else 1
        new = []
        for rr, cc in comp:
            ncc = cc + dy
            if side == 'L' and ncc < left_l:
                ncc = left_l
            if side == 'R' and ncc > right_r:
                ncc = right_r
            new.append((rr, ncc))
        return new

    def mirror(comp, side):
        res = []
        for rr, cc in comp:
            ncc = mirror_col(cc, side)
            res.append((rr, ncc))
        # If the mirrored component overlaps the wall (because the wall has
        # width), push it away from the wall until it is clear.
        while True:
            bad = False
            for rr, cc in res:
                if a <= cc <= b:
                    bad = True
                    break
            if not bad:
                break
            step = -1 if side == 'L' else 1
            res = [(rr, cc + step) for rr, cc in res]
        return res

    final_cells = []
    for comp in left_comps:
        if side_touch_wall('L', comp):
            moved = shift(comp, 'L', to_wall=False)
        else:
            moved = shift(comp, 'L', to_wall=True)
        final_cells.extend(mirror(moved, 'L'))

    for comp in right_comps:
        if side_touch_wall('R', comp):
            moved = shift(comp, 'R', to_wall=False)
        else:
            moved = shift(comp, 'R', to_wall=True)
        final_cells.extend(mirror(moved, 'R'))

    # Paint final cells.
    for rr, cc in final_cells:
        if 0 <= rr < h and 0 <= cc < w:
            if left_l <= cc <= left_r:
                bg = left_bg
            elif right_l <= cc <= right_r:
                bg = right_bg
            else:
                continue
            # colour from the original cell that produced it is not stored,
            # so repaint using the value currently still in the output
            # (which for non-erased cells is original).  To keep it simple,
            # we use the original grid value.
            out[rr][cc] = grid[rr][cc]

    # The above final painting uses grid[rr][cc] of the destination, which may
    # be background.  A more accurate method is to paint each component's own
    # colours directly.
    # Redo painting correctly.
    out = [row[:] for row in grid]

    for comp in left_comps:
        for rr, cc in comp:
            out[rr][cc] = left_bg
    for comp in right_comps:
        for rr, cc in comp:
            out[rr][cc] = right_bg

    def paint_moved(comp, side, to_wall):
        if side == 'L':
            dy = 1 if to_wall else -1
        else:
            dy = -1 if to_wall else 1

        for rr, cc, val in comp:
            ncc = cc + dy
            if side == 'L' and ncc < left_l:
                ncc = left_l
            if side == 'R' and ncc > right_r:
                ncc = right_r
            # mirror
            mcc = mirror_col(ncc, side)
            # if in wall, push away
            step = 1 if side == 'L' else -1
            while a <= mcc <= b:
                mcc += step
            if left_l <= mcc <= left_r:
                out[rr][mcc] = val
            elif right_l <= mcc <= right_r:
                out[rr][mcc] = val

    for comp in left_comps:
        comp_val = [(rr, cc, grid[rr][cc]) for rr, cc in comp]
        to_wall = not side_touch_wall('L', comp)
        paint_moved(comp_val, 'L', to_wall)

    for comp in right_comps:
        comp_val = [(rr, cc, grid[rr][cc]) for rr, cc in comp]
        to_wall = not side_touch_wall('R', comp)
        paint_moved(comp_val, 'R', to_wall)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    # Find the central vertical wall: a run of 2-3 identical non-background
    # columns that is not touching the outer left/right border and is present
    # in every row.
    wall_l = wall_r = -1
    wall_color = -1
    for c in range(2, W - 2):
        if all(grid[r][c] != 0 for r in range(H)):
            col = [grid[r][c] for r in range(H)]
            color = col[0]
            if all(v == color for v in col):
                # try widths 3 then 2
                for w in (3, 2):
                    c2 = c + w - 1
                    if c2 < W - 1:
                        if all(all(grid[r][cc] == color for cc in range(c, c + w)) for r in range(H)):
                            wall_l, wall_r = c, c2
                            wall_color = color
                            break
                if wall_l != -1:
                    break

    # Detect outer borders and interior backgrounds.
    def is_const_col(c, color):
        return all(grid[r][c] == color for r in range(H))

    left_bg = right_bg = -1
    left_wall_l = left_wall_r = right_wall_l = right_wall_r = -1

    # Left side: outer border may be 1-2 columns of a constant color.
    for bw in (1, 2):
        if bw < W and is_const_col(0, grid[0][0]) and all(is_const_col(c, grid[0][c]) for c in range(bw)):
            # interior background is the first column after the border that is not the border/wall
            for c in range(bw, wall_l if wall_l != -1 else W):
                if not is_const_col(c, grid[0][0]) and not is_const_col(c, wall_color):
                    # background color must be constant in this column
                    col = [grid[r][c] for r in range(H)]
                    if all(v == col[0] for v in col):
                        left_bg = col[0]
                        left_wall_l = bw
                        left_wall_r = c - 1
                        break
            if left_bg != -1:
                left_border_r = bw - 1
                break

    # Right side similarly.
    for bw in (1, 2):
        c = W - 1
        if is_const_col(c, grid[0][c]) and all(is_const_col(W - 1 - i, grid[0][W - 1 - i]) for i in range(bw)):
            for c in range(W - 1 - bw, (wall_r + 1) if wall_r != -1 else 0, -1):
                if not is_const_col(c, grid[0][W - 1]) and not is_const_col(c, wall_color):
                    col = [grid[r][c] for r in range(H)]
                    if all(v == col[0] for v in col):
                        right_bg = col[0]
                        right_wall_l = c + 1
                        right_wall_r = W - 1 - bw
                        break
            if right_bg != -1:
                right_border_l = W - bw
                break

    # If detection failed, fall back to a simple full-grid transformation.
    if left_bg == -1 or right_bg == -1 or wall_l == -1:
        out = [row[:] for row in grid]
        for r in range(H):
            for c in range(W):
                out[r][c] = grid[r][c]
        return out

    def components(cells):
        rem = set(cells)
        comps = []
        while rem:
            s = rem.pop()
            stack = [s]
            comp = [s]
            while stack:
                r, c = stack.pop()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if (nr, nc) in rem:
                        rem.remove((nr, nc))
                        stack.append((nr, nc))
                        comp.append((nr, nc))
            comps.append(comp)
        return comps

    left_cells = [
        (r, c)
        for r in range(H)
        for c in range(left_wall_l, left_wall_r + 1)
        if grid[r][c] != left_bg
    ]
    right_cells = [
        (r, c)
        for r in range(H)
        for c in range(right_wall_l, right_wall_r + 1)
        if grid[r][c] != right_bg
    ]

    left_comps = components(left_cells)
    right_comps = components(right_cells)

    # Erase objects.
    out = [row[:] for row in grid]
    for comp in left_comps:
        for r, c in comp:
            out[r][c] = left_bg
    for comp in right_comps:
        for r, c in comp:
            out[r][c] = right_bg

    def bounding(comp):
        rs = [r for r, _ in comp]
        cs = [c for _, c in comp]
        return min(rs), min(cs), max(rs), max(cs)

    # The rule is a vertical “bounce”:
    # 1. Reflect each object vertically within its own bounding box.
    # 2. Move it down by twice its height.
    # 3. If it leaves the bottom of the allowed interior, clamp it to the
    #    bottom and then flip it back vertically (as if it bounced on the
    #    bottom border).
    # 4. Keep the object's horizontal position and colours.
    def paint(comp, bg):
        rmin, cmin, rmax, cmax = bounding(comp)
        height = rmax - rmin + 1
        width = cmax - cmin + 1

        # Determine allowed vertical range for this object on its side.
        # Use the top/bottom borders of the whole grid as the bounces.
        top = 0
        bottom = H - 1

        # Reflect inside bbox: r' = rmin + rmax - r
        reflected = [(rmin + rmax - r, c) for r, c in comp]
        # Shift down by 2*height so the top of reflected bbox is rmax+1.
        shift = 2 * height
        moved = [(r + shift, c) for r, c in reflected]

        # If moved goes below bottom, clamp and flip back.
        max_row = max(r for r, _ in moved)
        if max_row > bottom:
            # Place bottom of the (reflected) shape at bottom.
            # Need a shift such that max moved row = bottom.
            delta = bottom - max_row
            moved = [(r + delta, c) for r, c in moved]
            # Flip vertically again around its own bbox after clamping.
            rr = [r for r, _ in moved]
            nmin, nmax = min(rr), max(rr)
            moved = [(nmin + nmax - r, c) for r, c in moved]

        # If it still goes above top (possible for very tall objects), clamp similarly.
        min_row = min(r for r, _ in moved)
        if min_row < top:
            delta = top - min_row
            moved = [(r + delta, c) for r, c in moved]
            rr = [r for r, _ in moved]
            nmin, nmax = min(rr), max(rr)
            moved = [(nmin + nmax - r, c) for r, c in moved]

        for (r, c), (_, oc) in zip(moved, comp):
            if 0 <= r < H and 0 <= c < W:
                out[r][c] = grid[oc[0]][oc[1]]

    for comp in left_comps:
        paint(comp, left_bg)
    for comp in right_comps:
        paint(comp, right_bg)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    A = np.array(grid, dtype=int)
    H, W = A.shape

    def is_mirror_color(c: int) -> bool:
        if c == 0:
            return False
        total = int((A == c).sum())
        if total == 0:
            return False
        h = int((A[:, :, 0] == c).sum())
        v = int((A[0, :, 0] == c).sum())
        return (h == 1 or v == 1) and h + v <= 2

    colors = [int(c) for c in np.unique(A) if c != 0]
    mirror = [c for c in colors if is_mirror_color(c)]

    if not mirror:
        return A.tolist()

    if len(mirror) == 1:
        mc = mirror[0]
        mc_cells = list(zip(*np.where(A == mc)))
        if len(mc_cells) == 1:
            mr, mc = mc_cells[0]
            if mr % 2 == 1:
                return np.fliplr(A).tolist()
            return np.flipud(A).tolist()
    else:
        mc1, mc2 = sorted(mirror)
        p1 = [p for p in zip(*np.where(A == mc1))]
        p2 = [p for p in zip(*np.where(A == mc2))]

        def orient(p1, p2):
            r1, c1 = p1[0]
            r2, c2 = p2[0]
            if r2 > r1:
                return 0
            if r2 < r1:
                return 1
            if c2 > c1:
                return 2
            return 3

        o = orient(p1, p2)
        if o == 0:
            return np.flipud(A).tolist()
        if o == 1:
            return np.fliplr(A).tolist()
        if o == 2:
            return A.tolist()
        return np.rot90(A, k=1).tolist()

    return A.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = [list(map(int, row)) for row in grid]
    h, w = len(g), len(g[0])

    def cells(color: int):
        return [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]

    def min_h(vlist):
        m = min(vlist)
        return {v - m for v in vlist}

    # Try all crops of the input.  A valid crop must contain:
    # - a border-like frame made of one color
    # - at least two other colors
    best = None
    for r0 in range(h):
        for r1 in range(r0, h):
            for c0 in range(w):
                for c1 in range(c0, w):
                    crop = [row[c0:c1 + 1] for row in g[r0:r1 + 1]]
                    colors = {v for row in crop for v in row if v != 0}
                    if len(colors) < 3:
                        continue

                    frame = None
                    for fc in colors:
                        cs = cells(fc)
                        cs = [(r - r0, c - c0) for (r, c) in cs
                              if r0 <= r <= r1 and c0 <= c <= c1]
                        if not cs:
                            continue
                        rs = {r for r, _ in cs}
                        ccs = {c for _, c in cs}
                        top = min(rs)
                        bot = max(rs)
                        left = min(ccs)
                        right = max(ccs)
                        if top != 0 or bot != len(crop) - 1 or left != 0 or right != len(crop[0]) - 1:
                            continue
                        # The frame color must appear on all four sides.
                        top_row = crop[top]
                        bot_row = crop[bot]
                        left_col = [crop[i][0] for i in range(len(crop))]
                        right_col = [crop[i][-1] for i in range(len(crop))]
                        if not any(v == fc for v in top_row):
                            continue
                        if not any(v == fc for v in bot_row):
                            continue
                        if not any(v == fc for v in left_col):
                            continue
                        if not any(v == fc for v in right_col):
                            continue

                        # The crop should be tight for the non-frame content too,
                        # because the output is a cropped view of the original.
                        inner = [(r, c) for r in range(len(crop))
                                 for c in range(len(crop[0]))
                                 if crop[r][c] != 0 and crop[r][c] != fc]
                        if inner:
                            irs = {r for r, _ in inner}
                            ics = {c for _, c in inner}
                            if min(irs) != 0 or max(irs) != len(crop) - 1:
                                continue
                            if min(ics) != 0 or max(ics) != len(crop[0]) - 1:
                                continue

                        # Prefer the largest consistent crop.
                        score = len(crop) * len(crop[0])
                        if best is None or score > best[0]:
                            best = (score, crop)

    if best is None:
        # Fallback: tight crop around all non-background cells.
        nz = [(r, c) for r in range(h) for c in range(w) if g[r][c] != 0]
        if nz:
            rmin = min(r for r, _ in nz)
            rmax = max(r for r, _ in nz)
            cmin = min(c for _, c in nz)
            cmax = max(c for _, c in nz)
            return [row[cmin:cmax + 1] for row in g[rmin:rmax + 1]]
        return []

    return best[1]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Count colors; ignore background 0.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return []

    # The frame color is the most frequent non-zero color.
    frame_color = max(counts.items(), key=lambda x: x[1])[0]

    # Tight bounding box of all cells with the frame color.
    rows = [r for r in range(h) if any(grid[r][c] == frame_color for c in range(w))]
    cols = [c for c in range(w) if any(grid[r][c] == frame_color for r in range(h))]

    r0, r1 = min(rows), max(rows)
    c0, c1 = min(cols), max(cols)

    return [
        [grid[r][c] for c in range(c0, c1 + 1)]
        for r in range(r0, r1 + 1)
    ]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    colors = {grid[r][c] for r in range(h) for c in range(w)}
    colors.discard(0)

    def bounding_box(color: int):
        rows = [r for r in range(h) if any(grid[r][c] == color for c in range(w))]
        cols = [c for c in range(w) if any(grid[r][c] == color for r in range(h))]
        if not rows or not cols:
            return None
        return min(rows), max(rows), min(cols), max(cols)

    def is_square_frame(color: int):
        box = bounding_box(color)
        if box is None:
            return None
        r0, r1, c0, c1 = box
        rh = r1 - r0 + 1
        ch = c1 - c0 + 1
        if rh != ch:
            return None
        # All outer border cells must be this color.
        for c in range(c0, c1 + 1):
            if grid[r0][c] != color or grid[r1][c] != color:
                return None
        for r in range(r0, r1 + 1):
            if grid[r][c0] != color or grid[r][c1] != color:
                return None
        return box

    best = None
    for color in colors:
        box = is_square_frame(color)
        if box is None:
            continue
        r0, r1, c0, c1 = box
        size = (r1 - r0 + 1) * (c1 - c0 + 1)
        # Prefer the largest valid frame; if tied, keep first deterministic choice.
        if best is None or size > best[0]:
            best = (size, r0, r1, c0, c1)

    if best is None:
        # Fallback: tight crop around all non-background cells.
        rows = [r for r in range(h) if any(grid[r][c] != 0 for c in range(w))]
        cols = [c for c in range(w) if any(grid[r][c] != 0 for r in range(h))]
        if not rows or not cols:
            return []
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)
    else:
        _, r0, r1, c0, c1 = best

    return [
        [grid[r][c] for c in range(c0, c1 + 1)]
        for r in range(r0, r1 + 1)
    ]

import numpy as np

