def _mask_pattern(sub):
    """Return a tuple of 1/0 cells indicating non-zero positions."""
    sub = np.asarray(sub)
    return tuple((sub > 0).astype(int).ravel())


def _normalize_cell(sub):
    """
    Convert a raw input cell into a canonical glyph key.
    If the raw pattern exactly matches a known template, use that key.
    Otherwise use its binary silhouette as the key.
    """
    sub = np.asarray(sub, dtype=int)
    mask = _mask_pattern(sub)

    for name, tpl in TEMPLATES.items():
        if mask == tuple(np.array(tpl).ravel()):
            return name
    for name, tpl in SMALL_TEMPLATES.items():
        if mask == tuple(np.array(tpl).ravel()):
            return name

    return mask


def _match_output_cell(key, size):
    """
    Find the output template for a given cell key.
    The examples require interpreting certain source glyphs as other glyphs:
      source 5 -> output 6
      source 8 -> output 8
      source 7 -> output 3 when 3x3, but output 8 is handled by templates.
    """
    # Special mappings inferred from the examples.
    if key == "5":
        out_name = "6"
    elif key == "8":
        out_name = "8"
    elif key == "7" and size == 3:
        out_name = "3"
    else:
        out_name = str(key) if isinstance(key, str) else None

    if out_name in TEMPLATES:
        return np.array(TEMPLATES[out_name], dtype=int)
    if out_name in SMALL_TEMPLATES:
        return np.array(SMALL_TEMPLATES[out_name], dtype=int)
    return None


def _find_5x5_cells(grid):
    """
    Detect whether the input uses the 5x5 glyph layout (example 3 / test 1).
    Returns (cell_rows, cell_cols) if detected, else None.
    """
    h, w = grid.shape
    # Need at least one 5x5 region.
    if h < 5 or w < 5:
        return None

    # Candidate starts: coordinates that are not on a 5-grid separator.
    # In the examples, glyph top-left corners are at multiples of 5,
    # while separator lines are at indices congruent to 4 modulo 5.
    row_starts = [r for r in range(0, h - 4) if r % 5 != 4]
    col_starts = [c for c in range(0, w - 4) if c % 5 != 4]

    if not row_starts or not col_starts:
        return None

    good_rows = []
    for r in row_starts:
        row_ok = True
        for c in col_starts:
            sub = grid[r:r + 5, c:c + 5]
            vals = np.unique(sub[sub > 0])
            # A valid glyph has exactly one non-zero color.
            if len(vals) != 1:
                row_ok = False
                break
        if row_ok:
            good_rows.append(r)

    if not good_rows:
        return None

    # Choose the largest contiguous run of starts.
    best_rows = []
    cur = [good_rows[0]]
    for r in good_rows[1:]:
        if r == cur[-1] + 1:
            cur.append(r)
        else:
            if len(cur) > len(best_rows):
                best_rows = cur
            cur = [r]
    if len(cur) > len(best_rows):
        best_rows = cur

    if not best_rows:
        return None

    best_cols = []
    good_cols = []
    for c in col_starts:
        col_ok = True
        for r in best_rows:
            sub = grid[r:r + 5, c:c + 5]
            vals = np.unique(sub[sub > 0])
            if len(vals) != 1:
                col_ok = False
                break
        if col_ok:
            good_cols.append(c)

    if not good_cols:
        return None

    cur = [good_cols[0]]
    for c in good_cols[1:]:
        if c == cur[-1] + 1:
            cur.append(c)
        else:
            if len(cur) > len(best_cols):
                best_cols = cur
            cur = [c]
    if len(cur) > len(best_cols):
        best_cols = cur

    if not best_cols:
        return None

    return best_rows, best_cols


def _find_3x3_cells(grid):
    """
    Detect whether the input uses the 3x3 glyph layout (examples 1-2 / test 2).
    Returns (cell_rows, cell_cols) if detected, else None.
    """
    h, w = grid.shape
    if h < 3 or w < 3:
        return None

    row_starts = [r for r in range(0, h - 2) if r % 3 != 2]
    col_starts = [c for c in range(0, w - 2) if c % 3 != 2]

    if not row_starts or not col_starts:
        return None

    good_rows = []
    for r in row_starts:
        row_ok = True
        for c in col_starts:
            sub = grid[r:r + 3, c:c + 3]
            vals = np.unique(sub[sub > 0])
            if len(vals) != 1:
                row_ok = False
                break
        if row_ok:
            good_rows.append(r)

    if not good_rows:
        return None

    best_rows = []
    cur = [good_rows[0]]
    for r in good_rows[1:]:
        if r == cur[-1] + 1:
            cur.append(r)
        else:
            if len(cur) > len(best_rows):
                best_rows = cur
            cur = [r]
    if len(cur) > len(best_rows):
        best_rows = cur

    if not best_rows:
        return None

    good_cols = []
    for c in col_starts:
        col_ok = True
        for r in best_rows:
            sub = grid[r:r + 3, c:c + 3]
            vals = np.unique(sub[sub > 0])
            if len(vals) != 1:
                col_ok = False
                break
        if col_ok:
            good_cols.append(c)

    if not good_cols:
        return None

    best_cols = []
    cur = [good_cols[0]]
    for c in good_cols[1:]:
        if c == cur[-1] + 1:
            cur.append(c)
        else:
            if len(cur) > len(best_cols):
                best_cols = cur
            cur = [c]
    if len(cur) > len(best_cols):
        best_cols = cur

    if not best_cols:
        return None

    return best_rows, best_cols


def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.array(grid, dtype=int)
    h, w = arr.shape

    found5 = _find_5x5_cells(arr)
    found3 = _find_3x3_cells(arr)

    # Prefer the layout that gives more total cells and matches the input scale.
    score5 = len(found5[0]) * len(found5[1]) if found5 else 0
    score3 = len(found3[0]) * len(found3[1]) if found3 else 0

    if found5 and (not found3 or score5 >= score3):
        rows, cols = found5
        size = 5
    elif found3:
        rows, cols = found3
        size = 3
    else:
        # Fallback: assume 5x5 at the top-left grid.
        rows = list(range(0, max(0, h - 4), 5))
        cols = list(range(0, max(0, w - 4), 5))
        size = 5

    # The final row of the input contains the palette: one special non-zero color per column block.
    # Map each source glyph key to the color appearing under that source's column in the bottom row.
    palette = {}
    bottom = arr[-1]
    for ci, c in enumerate(cols):
        sub = bottom[-1, c:c + size] if arr.shape[0] > 0 else None
        vals = sub[sub > 0]
        if vals.size == 1:
            palette[(ci, size)] = int(vals[0])

    out_rows = len(rows) * size
    out_cols = len(cols) * size
    out = np.zeros((out_rows, out_cols), dtype=int)

    for ri, r in enumerate(rows):
        for ci, c in enumerate(cols):
            raw = arr[r:r + size, c:c + size]
            key = _normalize_cell(raw)
            tpl = _match_output_cell(key, size)
            if tpl is None:
                # Unknown pattern: fall back to the source silhouette.
                tpl = (raw > 0).astype(int)

            color = 0
            # Use the palette if available; otherwise use the source color.
            if (ci, size) in palette:
                color = palette[(ci, size)]
            else:
                vals = raw[raw > 0]
                if vals.size:
                    color = int(vals[0])

            if color != 0:
                block = (tpl == 1) * color
            else:
                block = np.zeros_like(tpl, dtype=int)

            out[ri * size:(ri + 1) * size, ci * size:(ci + 1) * size] = block

    return out.tolist()

import numpy as np
from collections import deque, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Most frequent colour is the background.
    bg = int(np.bincount(a.ravel()).argmax())

    # Connected components of non-background cells using 8-connectivity.
    visited = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and not visited[r, c]:
                q = deque([(r, c)])
                visited[r, c] = True
                cells = []
                colours = set()
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    colours.add(int(a[x, y]))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w:
                                if not visited[nx, ny] and a[nx, ny] != bg:
                                    visited[nx, ny] = True
                                    q.append((nx, ny))
                comps.append((cells, colours))

    out = a.copy()

    # If only one component exists, colour it.
    if len(comps) == 1:
        cells, colours = comps[0]
        if len(colours) == 1:
            col = next(iter(colours))
            for r, c in cells:
                out[r, c] = 3 if col < 5 else 5
        elif len(colours) == 2:
            c1, c2 = sorted(colours)
            for r, c in cells:
                v = int(a[r, c])
                if v == c1:
                    out[r, c] = 5
                elif v == c2:
                    out[r, c] = 3
        return out.tolist()

    # Group adjacent components into meta-components by Chebyshev distance <= 1.
    meta_rep = list(range(len(comps)))

    def find(i):
        while meta_rep[i] != i:
            meta_rep[i] = meta_rep[meta_rep[i]]
            i = meta_rep[i]
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            meta_rep[rj] = ri

    # Fast bounding-box check before exact distance check.
    for i in range(len(comps)):
        ri, ci = find(i), i
        for j in range(i + 1, len(comps)):
            if find(j) == ri:
                continue
            for (r1, c1) in comps[i][0]:
                for (r2, c2) in comps[j][0]:
                    if max(abs(r1 - r2), abs(c1 - c2)) <= 1:
                        union(i, j)
                        break
                else:
                    continue
                break

    metas = defaultdict(list)
    for i in range(len(comps)):
        metas[find(i)].append(i)

    best = None
    best_score = -1

    for items in metas.values():
        colours = set()
        for i in items:
            colours.update(comps[i][1])
        if len(colours) != 2:
            continue
        c1, c2 = sorted(colours)
        score = 0
        for i in items:
            for r, c in comps[i][0]:
                v = int(a[r, c])
                if v == c1:
                    score += 10
                elif v == c2:
                    score += 1
        if score > best_score:
            best_score = score
            best = (items, c1, c2)

    if best is None:
        return out.tolist()

    items, c1, c2 = best
    for i in items:
        for r, c in comps[i][0]:
            v = int(a[r, c])
            if v == c1:
                out[r, c] = 5
            elif v == c2:
                out[r, c] = 3

    return out.tolist()

import numpy as np
from collections import deque, Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    if a.size == 0:
        return []
    h, w = a.shape

    # Background is the most frequent color.
    bg = int(np.argmax(np.bincount(a.ravel(), minlength=10)))
    out = a.copy()

    # Connected components of non-background cells using 8-connectivity.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and not seen[r, c]:
                cells = []
                q = deque([(r, c)])
                seen[r, c] = True
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w and not seen[nx, ny] and a[nx, ny] != bg:
                                seen[nx, ny] = True
                                q.append((nx, ny))
                comps.append(cells)

    def component_score(cells):
        # We want a component that contains exactly two non-background colors.
        cnt = Counter(int(a[r, c]) for r, c in cells)
        if len(cnt) != 2:
            return None
        cols, sizes = zip(*cnt.most_common())
        if cols[0] == cols[1]:
            return None
        # In all valid cases, one color is the sparse compact endpoint color,
        # the other is the denser path color.
        if sizes[0] >= sizes[1]:
            path_col, block_col = cols[0], cols[1]
        else:
            path_col, block_col = cols[1], cols[0]

        # Score by how strongly the color cells follow a path:
        # path color should have high 8-neighbor density, block color should be compact.
        def density(col):
            s = 0
            for r, c in cells:
                if int(a[r, c]) == col:
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nr, nc = r + dx, c + dy
                            if 0 <= nr < h and 0 <= nc < w and int(a[nr, nc]) == col:
                                s += 1
            return s / cnt[col]

        score = density(path_col) - density(block_col) + 1.0
        return score, path_col, block_col

    best = None
    for cells in comps:
        cand = component_score(cells)
        if cand is not None:
            score, path_col, block_col = cand
            if best is None or score > best[0]:
                best = (score, path_col, block_col, cells)

    if best is not None:
        _, path_col, block_col, cells = best
        for r, c in cells:
            v = int(a[r, c])
            if v == path_col:
                out[r, c] = 5
            elif v == block_col:
                out[r, c] = 3

    return out.tolist()

