from collections import deque, Counter, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # Background is the most frequent colour.
    bg = int(np.argmax(np.bincount(a.ravel(), minlength=10)))

    # 8-connected components of non-background cells.
    visited = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and not visited[r, c]:
                cells = []
                q = deque([(r, c)])
                visited[r, c] = True
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w and not visited[nx, ny] and a[nx, ny] != bg:
                                visited[nx, ny] = True
                                q.append((nx, ny))
                comps.append(cells)

    def score_component(cells):
        counts = Counter(int(a[r, c]) for r, c in cells)
        if len(counts) != 2:
            return None

        # In the examples, the transformed component is a compact two-colour object:
        # one colour forms a line/path (colour A), the other forms thicker blocks/endpoints (colour B).
        # Score by how much colour B looks thicker than colour A.
        def neighbor_density(color):
            total = 0
            cnt = 0
            for r, c in cells:
                if int(a[r, c]) != color:
                    continue
                cnt += 1
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nr, nc = r + dx, c + dy
                        if 0 <= nr < h and 0 <= nc < w and int(a[nr, nc]) == color:
                            total += 1
            return total / cnt if cnt else 0.0

        (col1, cnt1), (col2, cnt2) = sorted(counts.items())
        score = abs(neighbor_density(col2) - neighbor_density(col1))
        # Prefer components that are large and genuinely two-coloured.
        score *= len(cells)
        return score, col1, col2

    best = None
    for cells in comps:
        cand = score_component(cells)
        if cand is not None:
            score, c1, c2 = cand
            if best is None or score > best[0]:
                best = (score, c1, c2, cells)

    if best is None:
        return out.tolist()

    _, c1, c2, cells = best
    d1 = 0
    d2 = 0
    for r, c in cells:
        if int(a[r, c]) == c1:
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    nr, nc = r + dx, c + dy
                    if 0 <= nr < h and 0 <= nc < w and int(a[nr, nc]) == c1:
                        d1 += 1
        else:
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    nr, nc = r + dx, c + dy
                    if 0 <= nr < h and 0 <= nc < w and int(a[nr, nc]) == c2:
                        d2 += 1

    # The thicker / blockier colour becomes 3, the thinner / path colour becomes 5.
    if d1 / max(1, Counter(int(a[r, c]) for r, c in cells)[c1]) <= d2 / max(1, Counter(int(a[r, c]) for r, c in cells)[c2]):
        thin, thick = c1, c2
    else:
        thin, thick = c2, c1

    for r, c in cells:
        v = int(a[r, c])
        if v == thick:
            out[r, c] = 3
        elif v == thin:
            out[r, c] = 5

    return out.tolist()

import numpy as np
from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    if h == 0 or w == 0:
        return out.tolist()

    # Background = most frequent color
    bg = int(Counter(a.ravel()).most_common(1)[0][0])

    # Two most frequent non-background colors
    nonbg_counts = Counter()
    for v in a.ravel():
        if v != bg:
            nonbg_counts[int(v)] += 1

    if not nonbg_counts:
        return out.tolist()

    if len(nonbg_counts) == 1:
        return out.tolist()

    c1, c2 = nonbg_counts.most_common(2)
    c1, c2 = int(c1[0]), int(c2[0])

    mask = (a == c1) | (a == c2)

    # Largest 8-connected component of the two candidate colors
    seen = np.zeros((h, w), dtype=bool)
    best_cells = []

    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w:
                                if mask[nx, ny] and not seen[nx, ny]:
                                    seen[nx, ny] = True
                                    q.append((nx, ny))
                if len(cells) > len(best_cells):
                    best_cells = cells

    if not best_cells:
        return out.tolist()

    cnt1 = sum(1 for r, c in best_cells if a[r, c] == c1)
    cnt2 = len(best_cells) - cnt1

    if cnt1 >= cnt2:
        more, less = c1, c2
    else:
        more, less = c2, c1

    for r, c in best_cells:
        if a[r, c] == more:
            out[r, c] = 5
        elif a[r, c] == less:
            out[r, c] = 3

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    H, W = g.shape

    # collect all non-zero pixels in row-major order
    pixels = []
    for r in range(H):
        for c in range(W):
            v = int(g[r, c])
            if v != 0:
                pixels.append((r, c, v))

    total = len(pixels)
    if total == 0:
        return [[0]]

    # find a square side length whose area is at least total
    n = int(np.ceil(np.sqrt(total)))
    while n * n < total:
        n += 1

    out = [[0] * n for _ in range(n)]

    # fill the output row by row with the non-zero pixels from the input
    idx = 0
    for r in range(n):
        for c in range(n):
            if idx < total:
                out[r][c] = pixels[idx][2]
                idx += 1

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Find 8-connected components of non-zero pixels
    visited = [[False]*W for _ in range(H)]
    objects = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not visited[r][c]:
                q = deque([(r, c)])
                visited[r][c] = True
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < H and 0 <= nc < W:
                                if not visited[nr][nc] and grid[nr][nc] != 0:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                objects.append(cells)

    if not objects:
        return [[0]]

    # Sort by top-left position
    objects.sort(key=lambda cells: (min(r for r, c in cells), min(c for r, c in cells)))

    # Compute bounding boxes
    bbs = []
    for cells in objects:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        bbs.append((min(rs), max(rs), min(cs), max(cs)))

    # Cell size
    s = max(max(b[1] - b[0] + 1, b[3] - b[2] + 1) for b in bbs)

    # Compute output size
    max_row = 0
    max_col = 0
    for i in range(len(objects)):
        b = bbs[i]
        h = b[1] - b[0] + 1
        w = b[3] - b[2] + 1
        if i == 0:
            pr, pc = 0, 0
        elif i == 1:
            pr, pc = s, 2*s - w
        elif i == 2:
            pr, pc = s - h, 0
        else:
            pr, pc = 2*s - h, 2*s - w
        max_row = max(max_row, pr + h)
        max_col = max(max_col, pc + w)

    # Create output grid
    out = [[0]*max_col for _ in range(max_row)]

    # Place objects in order (later objects overwrite earlier ones on overlap)
    for i in range(len(objects)):
        b = bbs[i]
        r0, r1, c0, c1 = b
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if i == 0:
            pr, pc = 0, 0
        elif i == 1:
            pr, pc = s, 2*s - w
        elif i == 2:
            pr, pc = s - h, 0
        else:
            pr, pc = 2*s - h, 2*s - w

        for (r, c) in objects[i]:
            orr = pr + (r - r0)
            occ = pc + (c - c0)
            out[orr][occ] = grid[r][c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Find the single non-background color used as the outline.
    # Background is 8 in all examples/test; 0 is also treated as background.
    nonbg = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 8 and v != 0:
                nonbg.add(v)

    if not nonbg:
        return out

    col = next(iter(nonbg))
    outline = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == col:
                outline.add((r, c))

    # Background cells not connected to the outside via 4-neighbor steps
    # while avoiding outline cells are filled with 2.
    bg = 8
    fill = 2

    visited = [[False] * w for _ in range(h)]
    stack = []

    # Seed all border background cells.
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and not visited[r][c]:
                visited[r][c] = True
                stack.append((r, c))
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and not visited[r][c]:
                visited[r][c] = True
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                if grid[nr][nc] == bg:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
                else:
                    # If it is outline or another non-bg pixel, mark as not exterior bg.
                    visited[nr][nc] = True

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and not visited[r][c]:
                out[r][c] = fill

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    n = len(grid)
    m = len(grid[0])
    out = [row[:] for row in grid]

    # Determine the sparse "boundary" color: the only color that is not 8/0
    # in most of the examples.  If there are several, pick the most frequent
    # non-background color.
    colors = {}
    for row in grid:
        for v in row:
            if v != 8 and v != 0:
                colors[v] = colors.get(v, 0) + 1

    if not colors:
        return out

    boundary_color = max(colors.items(), key=lambda x: x[1])[0]
    interior_color = 2

    # Points of the boundary color.
    pts = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == boundary_color]

    # If no meaningful boundary, leave input unchanged.
    if len(pts) < 4:
        return out

    # The shape is a rotated square / diamond.  Its four extreme points are
    # the topmost, leftmost, bottommost, and rightmost boundary pixels.
    top = min(pts, key=lambda p: (p[0], p[1]))
    bottom = max(pts, key=lambda p: (p[0], p[1]))
    left = min(pts, key=lambda p: (p[1], p[0]))
    right = max(pts, key=lambda p: (p[1], p[0]))

    # Remove any duplicate extreme point.
    verts = []
    for p in (top, left, bottom, right):
        if p not in verts:
            verts.append(p)

    # Need at least a quadrilateral to fill.
    if len(verts) < 4:
        return out

    def inside_rotated_square(r, c, vtop, vleft, vbot, vright):
        """
        Return True if (r, c) lies inside the diamond with vertices
        vtop, vleft, vbot, vright, using the same row/column range logic
        visible in the examples.
        """
        if r < vtop[0] or r > vbot[0]:
            return False

        # Left boundary: line from top to left and left to bottom.
        # Right boundary: line from top to right and right to bottom.
        # Use inclusive integer bounds.

        # Function to get the smallest column on the left edge for row r.
        def edge_col_a_to_b(a, b, r):
            r0, c0 = a
            r1, c1 = b
            if r0 == r1:
                return min(c0, c1)
            # linear interpolation: c = c0 + (c1-c0)*(r-r0)/(r1-r0)
            # use exact integer arithmetic with floor/ceil.
            num = (c1 - c0) * (r - r0)
            den = (r1 - r0)
            if den < 0:
                num = -num
                den = -den
            if num >= 0:
                return c0 + num // den
            else:
                return c0 + (num - den + 1) // den

        # For each row, leftmost interior column is just to the right of the
        # left edge, and rightmost interior column is just to the left of the
        # right edge.
        if vtop[0] <= r <= vleft[0]:
            left_col = edge_col_a_to_b(vtop, vleft, r)
            right_col = edge_col_a_to_b(vtop, vright, r)
        elif vleft[0] <= r <= vbot[0]:
            left_col = edge_col_a_to_b(vleft, vbot, r)
            right_col = edge_col_a_to_b(vright, vbot, r)
        else:
            return False

        return left_col < c < right_col

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 8 and inside_rotated_square(i, j, top, left, bottom, right):
                out[i][j] = interior_color

    return out

