            r2, c2 = poly[(i + 1) % n]
            # Cross product of edge (r2-r1, c2-c1) with point - vertex1.
            cp = (r2 - r1) * (col - c1) - (c2 - c1) * (row - r1)
            if cp > 0:
                if sgn == -1:
