def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    bg = grid[0][0]

    # Background colour is the colour of the top-left cell.
    # Find large full-width strips:
    #   left/right cells are the strip border colour,
    #   all interior cells are the strip fill colour,
    #   and the strip is at least 2 rows high.
    strips = []
    r = 0
    while r < H:
        if grid[r][0] != bg and grid[r][W - 1] != bg and grid[r][0] == grid[r][W - 1]:
            border = grid[r][0]
            r1 = r
            fill = None
            while (
                r1 < H
                and grid[r1][0] == border
                and grid[r1][W - 1] == border
                and all(c == grid[r1][0] for c in grid[r1]) is False
                and all(c == grid[r1][1] for c in grid[r1][1:-1])
            ):
                if fill is None:
                    fill = grid[r1][1]
                r1 += 1
            if r1 - r >= 2 and fill is not None:
                strips.append((r, r1 - 1, border, fill))
                r = r1
            else:
                r += 1
        else:
            r += 1

    if not strips:
        return [row[:] for row in grid]

    # Find solid rectangular "source" objects above the first strip.
    limit = strips[0][0]
    seen = [[False] * W for _ in range(H)]
    sources = []
    for i in range(limit):
        for j in range(W):
            if seen[i][j] or grid[i][j] == bg:
                continue
            stack = [(i, j)]
            seen[i][j] = True
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < limit and 0 <= ny < W and not seen[nx][ny] and grid[nx][ny] != bg:
                        seen[nx][ny] = True
                        stack.append((nx, ny))

            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            if len(cells) == (y1 - y0 + 1) * (x1 - x0 + 1):
                src = [[grid[x][y] for y in range(x0, x1 + 1)] for x in range(y0, y1 + 1)]
                sources.append((x0, y0, x1, y1, src))

    # Start from clean background.
    out = [[bg] * W for _ in range(H)]

    # For each strip, place the first source rectangle whose colour set matches
    # the strip's colour set.  Recolour: source border colour -> strip border,
    # source fill colour -> strip fill.
    for srow, erow, border, fill in strips:
        chosen = None
        for x0, y0, x1, y1, src in sources:
            colors = set(c for row in src for c in row)
            if colors == {border, fill}:
                chosen = (x0, y0, x1, y1, src)
                break

        if chosen is None:
            # Draw the empty strip.
            for y in range(srow, erow + 1):
                for x in range(W):
                    out[y][x] = border if x in (0, W - 1) else fill
            continue

        x0, y0, x1, y1, src = chosen
        sh = y1 - y0 + 1
        sw = x1 - x0 + 1

        # Draw the empty strip.
        for y in range(srow, erow + 1):
            for x in range(W):
                out[y][x] = border if x in (0, W - 1) else fill

        # Map source colours to strip colours.
        src_colors = []
        for row in src:
            for c in row:
                if c not in src_colors:
                    src_colors.append(c)

        # Infer which source colour is the border colour:
        # it must be present on the top/bottom rows or left/right columns.
        border_src = None
        if len(src_colors) == 2:
            a, b = src_colors
            def is_border_color(col):
                return (
                    any(src[0][j] == col for j in range(sw))
                    or any(src[sh - 1][j] == col for j in range(sw))
                    or any(src[i][0] == col for i in range(sh))
                    or any(src[i][sw - 1] == col for i in range(sh))
                )
            if is_border_color(a):
                border_src = a
                fill_src = b
            else:
                border_src = b
                fill_src = a
        else:
            # Solid rectangle: use the only colour as the border colour.
            border_src = fill_src = src_colors[0]

        # Centred placement, clamped to the strip interior.
        ih = erow - srow + 1
        iw = W
        oy = srow + max(0, min((ih - sh) // 2, ih - sh))
        ox = max(0, min((iw - sw) // 2, iw - sw))
        oy = max(srow, min(oy, erow - sh + 1))
        ox = max(0, min(ox, W - sw))

        for i in range(sh):
            for j in range(sw):
                c = src[i][j]
                if c == border_src:
                    val = border
                elif c == fill_src:
                    val = fill
                else:
                    val = c
                out[oy + i][ox + j] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    h = len(grid)
    w = len(grid[0])

    bg = None
    obj = None
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    if not counts:
        return [list(row) for row in grid]

    # The background is the most frequent colour; the object is the most
    # frequent non-background colour.
    bg = max(counts, key=lambda k: counts[k])
    candidates = {k: v for k, v in counts.items() if k != bg}
    if candidates:
        obj = max(candidates, key=lambda k: candidates[k])
    else:
        return [list(row) for row in grid]

    # Cells that are "fixed anchors": object cells that have at least two
    # object neighbours in the same row or column.
    anchors = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != obj:
                continue
            horiz = 0
            if c > 0 and grid[r][c - 1] == obj:
                horiz += 1
            if c + 1 < w and grid[r][c + 1] == obj:
                horiz += 1
            vert = 0
            if r > 0 and grid[r - 1][c] == obj:
                vert += 1
            if r + 1 < h and grid[r + 1][c] == obj:
                vert += 1
            if horiz >= 2 or vert >= 2:
                anchors[r][c] = True

    out = [list(row) for row in grid]

    # For every non-object row, try to connect anchor cells that lie on that
    # row's implicit column range.  This completes horizontal lines while
    # preserving background cells that should remain background.
    for r in range(h):
        cols = [c for c in range(w) if anchors[r][c]]
        if len(cols) < 2:
            continue
        lo, hi = min(cols), max(cols)

        # The whole interval must currently be object/background.
        interval_ok = all(out[r][c] in (obj, bg) for c in range(lo, hi + 1))
        if not interval_ok:
            continue

        # The endpoints must be plausibly connected vertically, either by an
        # anchor on that column or by an unbroken vertical object strip.
        def endpoint_supported(c: int) -> bool:
            for rr in range(h):
                if anchors[rr][c]:
                    return True
            ok = True
            for rr in range(h):
                if out[rr][c] not in (obj, bg):
                    ok = False
                    break
                if rr != r and out[rr][c] == bg:
                    # A single isolated background gap is tolerated, matching
                    # the examples where one-cell vertical breaks are filled.
                    before_obj = rr > 0 and out[rr - 1][c] == obj
                    after_obj = rr + 1 < h and out[rr + 1][c] == obj
                    if not (before_obj and after_obj):
                        ok = False
                        break
            return ok

        if not (endpoint_supported(lo) and endpoint_supported(hi)):
            continue

        # Fill the interval between anchors on this row.
        for c in range(lo, hi + 1):
            out[r][c] = obj

    return out

