    def in_box(pt, box):
        y, x = pt
        return box[0] <= y <= box[1] and box[2] <= x <= box[3]

    def adjacent(i, j):
        if i == j:
            return False
        # bounding boxes with a small gap
        if (abs(boxes[i][0] - boxes[j][1]) > 2 or
            abs(boxes[j][0] - boxes[i][1]) > 2 or
            abs(boxes[i][2] - boxes[j][3]) > 2 or
            abs(boxes[j][2] - boxes[i][3]) > 2):
            return False
        # exact 8-neighbour adjacency between cells
        bi, bj = set(components[i]), set(components[j])
        for y, x in components[i]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if (y + dy, x + dx) in bj:
                        return True
        return False

    # find anchor components: the only ones that touch several different colours
    anchors = []
    for i in range(len(components)):
        touched = set()
        for p in components[i]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    q = (p[0] + dy, p[1] + dx)
                    if q in comp_id and q not in components[i]:
                        touched.add(int(a[q[0], q[1]]))
        if len(touched) >= 2:
            anchors.append(i)

    if not anchors:
        return out.tolist()

    # choose the anchor with maximum distinct neighbours; if tie, smallest colour
    def anchor_key(i):
        touched = set()
        for p in components[i]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    q = (p[0] + dy, p[1] + dx)
                    if q in comp_id and q not in components[i]:
                        touched.add(int(a[q[0], q[1]]))
        return (len(touched), -min(int(a[p[0], p[1]]) for p in components[i]))

    anchor = max(anchors, key=anchor_key)

    # find the other colour component that is opposite the main non-anchor colour across the anchor
    anchor_colors = set(int(a[y, x]) for (y, x) in components[anchor])

    # collect all non-anchor components adjacent to the anchor
    adjacent_to_anchor = [j for j in range(len(components))
                          if j != anchor and adjacent(j, anchor)]

    if not adjacent_to_anchor:
        return out.tolist()

    # choose the adjacent component whose colour does not appear in the anchor
    # if several, choose the one most distinct (not in anchor) and nearest
    candidates = []
    for j in adjacent_to_anchor:
        col = int(a[components[j][0][0], components[j][0][1]])
        candidates.append((col in anchor_colors, j))
    candidates.sort(key=lambda t: (t[0], t[1]))
    source = candidates[0][1]
    src_color = int(a[components[source][0][0], components[source][0][1]])

    # mirror transformation to try
    # 1) transpose about centre of source bbox (diagonal mirror)
    def mirror1(pt):
        y, x = pt
        y0, y1, x0, x1 = boxes[source]
        # map to local coordinates, transpose, then place opposite with same bbox dimensions
        ly = y - y0
        lx = x - x0
        ny = x0 + ly
        nx = y0 + lx
        return (ny, nx)

    # We want the target bounding box to be on the other side of the anchor,
    # symmetric to the source bbox with respect to the anchor bbox.
    ay0, ay1, ax0, ax1 = boxes[anchor]
    sy0, sy1, sx0, sx1 = boxes[source]

    # target bbox: reflect source bbox across anchor bbox centre
    # If anchor is thin/line, reflect across its line using midpoint.
    # Use exact centre arithmetic.
    t_y0 = 2 * ay0 - sy1
    t_y1 = 2 * ay1 - sy0
    t_x0 = 2 * ax0 - sx1
    t_x1 = 2 * ax1 - sx0

    # Ensure source height/width match target (they will for reflection)
    def local_to_target(ly, lx):
        # transpose source local coordinates, then place into target bbox
        ty = t_y0 + lx
        tx = t_x0 + ly
        return (ty, tx)

    # Generate mirrored cells for all source-coloured cells in the source component
    mirrored = set()
    for (y, x) in components[source]:
        if a[y, x] == src_color:
            ly = y - sy0
            lx = x - sx0
            ty, tx = local_to_target(ly, lx)
            if 0 <= ty < h and 0 <= tx < w:
                mirrored.add((ty, tx))

    # Place mirrored cells only on background cells, do not overwrite existing pixels
    for (ty, tx) in mirrored:
        if out[ty, tx] == bg:
            out[ty, tx] = src_color

    return out.tolist()

import numpy as np
from collections import deque, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Determine background
    border = np.concatenate([g[0, :], g[-1, :], g[:, 0], g[:, -1]])
    vals, counts = np.unique(border, return_counts=True)
    if len(vals) == 1:
        bg = int(vals[0])
    else:
        all_vals, all_counts = np.unique(g, return_counts=True)
        bg = int(all_vals[np.argmax(all_counts)])

    if not np.any(g == 2):
        return out.tolist()

    # Components of 2s, 8-connected
    two_mask = (g == 2)
    comp_id = np.full((H, W), -1, dtype=int)
    comps = []

    for i in range(H):
        for j in range(W):
            if two_mask[i, j] and comp_id[i, j] == -1:
                cid = len(comps)
                q = deque([(i, j)])
                comp_id[i, j] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if two_mask[ny, nx] and comp_id[ny, nx] == -1:
                                    comp_id[ny, nx] = cid
                                    q.append((ny, nx))
                comps.append(cells)

    if not comps:
        return out.tolist()

    # Nearest 2-pixel lookup for every cell by expanding rings from all 2 cells.
    nearest = [[None for _ in range(W)] for _ in range(H)]
    multi = deque()
    for i in range(H):
        for j in range(W):
            if two_mask[i, j]:
                nearest[i][j] = (i, j)
                multi.append((i, j))

    while multi:
        y, x = multi.popleft()
        ny = 2 * y - nearest[y][x][0]
        nx = 2 * x - nearest[y][x][1]
        if 0 <= ny < H and 0 <= nx < W and nearest[ny][nx] is None:
            nearest[ny][nx] = nearest[y][x]
            multi.append((ny, nx))

    # Classify each 2-component and build local reflection functions.
    # Reflection is performed relative to the nearest 2 cell, using the component's global line where possible.
    reflectors = []

    for cells in comps:
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        min_y, max_y = min(ys), max(ys)
        min_x, max_x = min(xs), max(xs)
        height = max_y - min_y + 1
        width = max_x - min_x + 1
        size = len(cells)

        # If component is essentially one row
        if height == 1:
            row = ys[0]
            # horizontal line: mirror vertically
            ref = lambda y, x, row=row: (2 * row - y, x)
            reflectors.append((min_y, max_y, min_x, max_x, ref))
        # If component is essentially one column
        elif width == 1:
            col = xs[0]
            # vertical line: mirror horizontally
            ref = lambda y, x, col=col: (y, 2 * col - x)
            reflectors.append((min_y, max_y, min_x, max_x, ref))
        # If single cell
        elif size == 1:
            cy, cx = cells[0]
            # point reflection
            ref = lambda y, x, cy=cy, cx=cx: (2 * cy - y, 2 * cx - x)
            reflectors.append((min_y, max_y, min_x, max_x, ref))
        else:
            # Try to fit a diagonal line if bounding box is thin.
            # For ARC-like shapes, diagonal mirror if all cells lie on y + x = c or y - x = c.
            sum_vals = {y + x for y, x in cells}
            diff_vals = {y - x for y, x in cells}

            if len(sum_vals) == 1:
                c = sum_vals.pop()
                # mirror across y + x = c: (y, x) -> (c - x, c - y)
                ref = lambda y, x, c=c: (c - x, c - y)
                reflectors.append((min_y, max_y, min_x, max_x, ref))
            elif len(diff_vals) == 1:
                c = diff_vals.pop()
                # mirror across y - x = c: (y, x) -> (x + c, y - c)
                ref = lambda y, x, c=c: (x + c, y - c)
                reflectors.append((min_y, max_y, min_x, max_x, ref))
            else:
                # Fallback: use the nearest 2 cell as a point center.
                # This is rarely needed for clean ARC grids.
                cy, cx = cells[0]
                ref = lambda y, x, cy=cy, cx=cx: (2 * cy - y, 2 * cx - x)
                reflectors.append((min_y, max_y, min_x, max_x, ref))

    # For each non-background, non-2 source pixel, reflect through its nearest 2.
    for i in range(H):
        for j in range(W):
            c = g[i, j]
            if c == bg or c == 2:
                continue
            center = nearest[i][j]
            if center is None:
                continue
            cy, cx = center
            cid = comp_id[cy, cx]
            if cid < 0:
                continue

            _, _, _, _, ref = reflectors[cid]
            my, mx = ref(i, j)

            if 0 <= my < H and 0 <= mx < W:
                if out[my, mx] == 2:
                    out[my, mx] = c

    return out.tolist()

