def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])

    def in_bounds(r, c):
        return 0 <= r < h and 0 <= c < w

    def is_bg(v):
        return v in (0, 1)

    out = [row[:] for row in grid]
    dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r in range(h):
        for c in range(w):
            if is_bg(grid[r][c]):
                continue

            color = grid[r][c]
            for dr, dc in dirs:
                r1, c1 = r + dr, c + dc
                if not in_bounds(r1, c1) or is_bg(grid[r1][c1]):
                    continue

                r2, c2 = r1 + dr, c1 + dc
                if not in_bounds(r2, c2) or is_bg(grid[r2][c2]):
                    continue

                mid_colors = {grid[r1][c1], grid[r2][c2]}
                if len(mid_colors) == 2 and all(v != color for v in mid_colors):
                    r3, c3 = r2 + dr, c2 + dc
                    while in_bounds(r3, c3) and grid[r3][c3] in mid_colors:
                        r3 += dr
                        c3 += dc

                    if in_bounds(r3, c3) and grid[r3][c3] == color:
                        rr, cc = r - dr, c - dc
                        while in_bounds(rr, cc):
                            if is_bg(out[rr][cc]):
                                out[rr][cc] = color
                            rr -= dr
                            cc -= dc

                        rr, cc = r3 + dr, c3 + dc
                        while in_bounds(rr, cc):
                            if is_bg(out[rr][cc]):
                                out[rr][cc] = color
                            rr += dr
                            cc += dc

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    out = [row[:] for row in grid]

    def is_bg(v: int) -> bool:
        return v == 0 or v == 1

    # Find the center of the color-3 diamond.
    # The diamond is exactly all non-bg cells with value 3 at Manhattan distance 2
    # from the center. There is one such center in the provided cases.
    centers = []
    for cr in range(h):
        for cc in range(w):
            ok = True
            for dr, dc in [(-2, 0), (2, 0), (0, -2), (0, 2),
                           (-1, -1), (-1, 1), (1, -1), (1, 1)]:
                r, c = cr + dr, cc + dc
                if not (0 <= r < h and 0 <= c < w) or grid[r][c] != 3:
                    ok = False
                    break
            if ok:
                centers.append((cr, cc))

    if not centers:
        return out

    cr, cc = centers[0]

    # Collect all non-bg, non-3 cells as colored seeds.
    seeds = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if not is_bg(v) and v != 3:
                seeds.append((r, c, v))

    if not seeds:
        return out

    def line_id(r, c, kind):
        # kind 0: slope +1 diagonal, c - r constant
        # kind 1: slope -1 diagonal, c + r constant
        if kind == 0:
            return (0, c - r)
        return (1, c + r)

    # For each diagonal line, if it has at least one seed, find the two extreme
    # seed colors and paint the entire line, stopping at existing object cells.
    lines = {}
    for r, c, v in seeds:
        for kind in (0, 1):
            lid = line_id(r, c, kind)
            lines.setdefault(lid, []).append((r, c, v))

    for lid, cells in lines.items():
        kind, _ = lid

        # If a line contains multiple colors, choose the color nearest the center
        # at each end. In the examples each line has one color, but this makes
        # the rule robust.
        if len(cells) == 1:
            color = cells[0][2]
            start = cells[0][0]
            end = cells[0][0]
        else:
            # Sort by projection along the line.
            if kind == 0:
                # direction (1, 1), projection r
                ordered = sorted(cells, key=lambda x: x[0])
            else:
                # direction (1, -1), projection r
                ordered = sorted(cells, key=lambda x: x[0])

            first = ordered[0]
            last = ordered[-1]

            # Pick the seed on each side closest to the center.
            def dist(cell):
                return abs(cell[0] - cr) + abs(cell[1] - cc)

            # For the low-r end, choose among cells at/below the midpoint.
            mid = (first[0] + last[0]) // 2
            left_candidates = [cell for cell in ordered if cell[0] <= mid]
            right_candidates = [cell for cell in ordered if cell[0] >= mid]
            if not left_candidates:
                left_candidates = [first]
            if not right_candidates:
                right_candidates = [last]

            left = min(left_candidates, key=dist)
            right = min(right_candidates, key=dist)

            # If both ends have the same color, use it; otherwise paint each side
            # separately. For simplicity, if colors differ, handle both rays.
            if left[2] == right[2]:
                color = left[2]
                start = left[0]
                end = right[0]
            else:
                # Paint left ray.
                def paint_ray(seed_r, seed_c, color, dr, dc):
                    r, c = seed_r, seed_c
                    while 0 <= r < h and 0 <= c < w:
                        if not is_bg(out[r][c]):
                            break
                        out[r][c] = color
                        r += dr
                        c += dc

                if kind == 0:
                    paint_ray(left[0], left[1], left[2], -1, -1)
                    paint_ray(right[0], right[1], right[2], 1, 1)
                else:
                    paint_ray(left[0], left[1], left[2], -1, 1)
                    paint_ray(right[0], right[1], right[2], 1, -1)
                continue

            color = color
            start = left[0]
            end = right[0]

        # Paint the whole line between the chosen extreme seeds.
        def paint_ray(seed_r, seed_c, color, dr, dc, stop_before=None):
            r, c = seed_r, seed_c
            while 0 <= r < h and 0 <= c < w:
                if stop_before is not None and r == stop_before[0] and c == stop_before[1]:
                    break
                if not is_bg(out[r][c]):
                    break
                out[r][c] = color
                r += dr
                c += dc

        # Direction vectors for the two diagonal families.
        if kind == 0:
            # slope +1: from start to end is (1, 1) or (1, -1)?
            # Since c-r is constant, moving in +r also moves +c.
            dr = 1
            dc = 1
            # Make sure start is the lower-r endpoint; if not, swap.
            if start[0] > end[0]:
                start, end = end, start
        else:
            # slope -1: c+r constant, moving +r moves -c.
            dr = 1
            dc = -1
            if start[0] > end[0]:
                start, end = end, start

        # Paint outward from both ends.
        paint_ray(start[0], start[1], color, -dr, -dc)
        paint_ray(end[0], end[1], color, dr, dc)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    def is_background(v: int) -> bool:
        return v == 0 or v == 1

    dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if is_background(v):
                continue

            for dr, dc in dirs:
                rr, cc = r, c
                while True:
                    rr += dr
                    cc += dc
                    if rr < 0 or rr >= h or cc < 0 or cc >= w:
                        break
                    if not is_background(out[rr][cc]):
                        break
                    out[rr][cc] = v

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]):
    g = np.array(grid, dtype=int)
    if g.size == 0:
        return g.tolist()

    colors, counts = np.unique(g, return_counts=True)
    # Exclude likely background: 0, or the most frequent color if 0 is absent.
    present = set(int(c) for c in colors)
    if 0 in present:
        nonbg_counts = {int(c): int(n) for c, n in zip(colors, counts) if int(c) != 0}
    else:
        # Use the most common color as background.
        bg = int(colors[np.argmax(counts)])
        nonbg_counts = {int(c): int(n) for c, n in zip(colors, counts) if int(c) != bg}

    nonbg = sorted(nonbg_counts.items(), key=lambda x: (-x[1], x[0]))
    if len(nonbg) >= 4:
        path = nonbg[0][0]
        srcA, srcB = nonbg[1][0], nonbg[2][0]
    else:
        # Fallback: rarest two are sources, most remaining is path.
        nonbg_asc = sorted(nonbg_counts.items(), key=lambda x: x[1])
        srcA, srcB = nonbg_asc[0][0], nonbg_asc[1][0]
        path = nonbg_asc[-1][0]

    out = g.copy()

    # Multi-source BFS over the path color from all source pixels.
    R, C = g.shape
    distA = [[-1] * C for _ in range(R)]
    distB = [[-1] * C for _ in range(R)]
    qA = []
    qB = []
    for i in range(R):
        for j in range(C):
            if g[i, j] == srcA:
                distA[i][j] = 0
                qA.append((i, j))
            elif g[i, j] == srcB:
                distB[i][j] = 0
                qB.append((i, j))

    def bfs(q, dist):
        head = 0
        while head < len(q):
            r, c = q[head]
            head += 1
            d = dist[r][c] + 1
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < R and 0 <= nc < C and g[nr, nc] == path and dist[nr][nc] == -1:
                    dist[nr][nc] = d
                    q.append((nr, nc))

    bfs(qA, distA)
    bfs(qB, distB)

    for i in range(R):
        for j in range(C):
        if g[i, j] == path:
            da, db = distA[i][j], distB[i][j]
            if da != -1 and db == -1:
                out[i, j] = srcA
            elif db != -1 and da == -1:
                out[i, j] = srcB
            # If both or neither can reach the cell, leave it as path.

    return out.tolist()

