def transform(grid: list[list[int]]) -> list[list[int]):
    h = len(grid)
    w = len(grid[0])

    # First pass: use already-present non-zero cells to fill zeros.
    work = [list(row) for row in grid]
    for r in range(h):
        for c in range(w):
            if work[r][c] == 0:
                if h - 1 - r < r and work[h - 1 - r][c] != 0:
                    work[r][c] = work[h - 1 - r][c]
                elif w - 1 - c < c and work[r][w - 1 - c] != 0:
                    work[r][c] = work[r][w - 1 - c]
                elif h - 1 - r > r and work[h - 1 - r][c] != 0:
                    work[r][c] = work[h - 1 - r][c]
                elif w - 1 - c > c and work[r][w - 1 - c] != 0:
                    work[r][c] = work[r][w - 1 - c]

    # Second pass: propagate the filled pattern by 180-degree symmetry.
    # The target test inputs can contain two opposite missing blocks, so a
    # single pass is not enough.
    work = np.array(work, dtype=int)
    changed = True
    while changed:
        changed = False
        flip = work[::-1, ::-1]
        mask = (work == 0) & (flip != 0)
        if np.any(mask):
            work = np.where(mask, flip, work)
            changed = True

    return work.tolist()

