            (max_r, min_c),
            (max_r, max_c),
        ]
        side = [
            (min_r, min_c + 1),
            (min_r + 1, min_c),
            (max_r, min_c + 1),
            (min_r + 1, max_c),
        ]
        for p in corners + side:
            if p in cellset:
                keep.add(p)

        # The final shape must be 3x3-connected and must retain at least one side.
        if len(keep) < 5:
            return None

        # BFS over keep using 8-connectivity.
        start = (cr, cc)
        vis = {start}
        stack = [start]
        while stack:
            x, y = stack.pop()
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    p = (x + dx, y + dy)
                    if p in keep and p not in vis:
                        vis.add(p)
                        stack.append(p)
        if vis != keep:
            return None

        return keep

    for r in range(H):
        for c in range(W):
            if (r, c) in seen:
                continue
            col = grid[r][c]
            if col == bg:
                seen.add((r, c))
                continue

            cells = flood(r, c, col)
            seen.update(cells)

            keep = clean_shape(cells)
            if keep is None:
                for x, y in cells:
                    out[x][y] = bg
            else:
                for x, y in cells:
                    if (x, y) not in keep:
                        out[x][y] = bg

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Background is the most frequent colour (tie broken by smaller colour).
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    out = [row[:] for row in grid]
    seen = set()

    def flood(r, c, col):
        stack = [(r, c)]
        seen.add((r, c))
        cells = []
        while stack:
            x, y = stack.pop()
            cells.append((x, y))
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and (nx, ny) not in seen:
                    if grid[nx][ny] == col:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
        return cells

    def canonical(cells):
        """Return the set of cells to keep for a 3x3 object, or None to erase."""
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)

        # Only 3x3 bounding boxes are repaired.
        if r1 - r0 != 2 or c1 - c0 != 2:
            return None

        cellset = set(cells)
        keep = set()

        # The centre must be present.
        cr, cc = r0 + 1, c0 + 1
        if (cr, cc) not in cellset:
            return None
        keep.add((cr, cc))

        corners = [
            (r0, c0),
            (r0, c1),
            (r1, c0),
            (r1, c1),
        ]
        side = [
            (r0, c0 + 1),
            (r1, c0 + 1),
            (r0 + 1, c0),
            (r0 + 1, c1),
        ]

        # Keep every present corner.
        for p in corners:
            if p in cellset:
                keep.add(p)

        # Keep up to one present side cell.
        # Prefer the side whose neighbour corner is missing, to preserve the
        # intended 3x3 "corner/side" pattern.  Break ties by top, then left.
        present_side = [p for p in side if p in cellset]
        if present_side:
            def side_score(p):
                rr, cc = p
                if rr == r0:
                    c = cc - 1
                elif rr == r1:
                    c = cc - 1
                else:
                    c = cc
                # missing corner has priority 0, present corner priority 1
                corner_missing = 0 if ((rr, c) not in cellset) else 1
                return (-corner_missing, rr, cc)
            keep.add(min(present_side, key=side_score))

        # Valid final object: centre + at least one kept corner + kept side(s),
        # and it must stay 8-connected.
        if len(keep) < 3:
            return None

        # 8-connectivity check.
        start = (cr, cc)
        vis = {start}
        stack = [start]
        while stack:
            x, y = stack.pop()
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    p = (x + dx, y + dy)
                    if p in keep and p not in vis:
                        vis.add(p)
                        stack.append(p)
        if vis != keep:
            return None

        return keep

    for r in range(H):
        for c in range(W):
            if (r, c) in seen:
                continue
            col = grid[r][c]
            if col == bg:
                seen.add((r, c))
                continue

            cells = flood(r, c, col)
            seen.update(cells)

            keep = canonical(cells)
            if keep is None:
                for x, y in cells:
                    out[x][y] = bg
            else:
                for x, y in cells:
                    if (x, y) not in keep:
                        out[x][y] = bg

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Use border color as background. If border is not uniform, choose the most
    # frequent color among border cells. This matches all provided cases.
    border = []
    for r in range(H):
        border.append(grid[r][0])
        border.append(grid[r][W - 1])
    for c in range(W):
        border.append(grid[0][c])
        border.append(grid[H - 1][c])

    cnt = {}
    for v in border:
        cnt[v] = cnt.get(v, 0) + 1
    bg = max(cnt.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    out = [row[:] for row in grid]

    # For each non-background color, find cells that participate in at least one
    # valid 3x3 pattern.
    keep = [[False] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == bg:
                continue
            keep[r][c] = True  # temporary; will be reset below per color pass

    # Better: process by color and only mark covered cells.
    colors = set()
    for row in grid:
        for v in row:
            if v != bg:
                colors.add(v)

    keep = [[False] * W for _ in range(H)]

    for col in colors:
        covered = [[False] * W for _ in range(H)]

        # Scan all 3x3 windows centered at (r, c).
        for r in range(1, H - 1):
            for c in range(1, W - 1):
                if grid[r][c] != col:
                    continue

                # The 8 neighbors in the 3x3 window.
                neigh = [
                    (r - 1, c - 1),
                    (r - 1, c),
                    (r - 1, c + 1),
                    (r, c - 1),
                    (r, c + 1),
                    (r + 1, c - 1),
                    (r + 1, c),
                    (r + 1, c + 1),
                ]

                present = []
                total = 1  # center
                for (nr, nc) in neigh:
                    if grid[nr][nc] == col:
                        present.append((nr, nc))
                        total += 1

                # Valid pattern: center plus at least two colored neighbors.
                # This preserves dense 3x3 tile structures and removes stray
                # one-pixel attachments.
                if len(present) >= 2:
                    covered[r][c] = True
                    for (nr, nc) in present:
                        covered[nr][nc] = True

        for r in range(H):
            for c in range(W):
                if grid[r][c] == col and covered[r][c]:
                    keep[r][c] = True

    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and not keep[r][c]:
                out[r][c] = bg

    return out

