def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    out = g.copy()
    H, W = g.shape

    # For every vertical run of a non-background color, if that run is
    # immediately bounded above and below by another color, and the bounding
    # color appears somewhere to the right on the same row, convert the run
    # to the bounding color.
    r = 0
    while r < H:
        c = 0
        while c < W:
            v = int(g[r, c])
            if v != 0:
                r2 = r
                while r2 + 1 < H and int(g[r2 + 1, c]) == v:
                    r2 += 1

                top = int(g[r - 1, c]) if r > 0 else 0
                bot = int(g[r2 + 1, c]) if r2 + 1 < H else 0

                if top != 0 and top == bot:
                    if np.any(g[r - 1, c + 1:] == top) and np.any(g[r2 + 1, c + 1:] == top):
                        out[r:r2 + 1, c] = top

                r = r2 + 1
            else:
                c += 1
        r += 1

    return out.tolist()

