from collections import deque

def transform(grid):
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components (4-connected) of each non-zero color
    visited = [[False]*w for _ in range(h)]
    components = []  # (color, set of (r,c))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                comp = set()
                dq = deque([(r, c)])
                visited[r][c] = True
                while dq:
                    cr, cc = dq.popleft()
                    comp.add((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            dq.append((nr, nc))
                components.append((color, comp))

    # For each component, determine if it should be replaced
    for color, comp in components:
        boundary_colors = set()
        for (r, c) in comp:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    val = grid[nr][nc]
                    if val != 0 and val != color:
                        boundary_colors.add(val)

        if len(boundary_colors) == 1:
            boundary_color = boundary_colors.pop()
            # Count occurrences of boundary_color in the entire grid
            bc_count = sum(1 for r in range(h) for c in range(w) if grid[r][c] == boundary_color)
            # Count how many of those are adjacent to this component
            adj_bc = set()
            for (r, c) in comp:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == boundary_color:
                        adj_bc.add((nr, nc))
            # Boundary color must ONLY appear as adjacent to this component
            if bc_count == len(adj_bc):
                for (r, c) in comp:
                    out[r][c] = boundary_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    background = int(np.bincount(g.ravel()).argmax())

    from collections import deque

    def components(color):
        mask = (g == color)
        seen = np.zeros((H, W), dtype=bool)
        out = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    comp = [(r, c)]
                    while q:
                        x, y = q.popleft()
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < H and 0 <= ny < W and mask[nx, ny] and not seen[nx, ny]:
                                seen[nx, ny] = True
                                q.append((nx, ny))
                                comp.append((nx, ny))
                    out.append(comp)
        return out

    groups = {}
    for color in range(1, 10):
        comps = components(color)
        groups[color] = [
            [min(r for r, c in comp), max(r for r, c in comp),
             min(c for r, c in comp), max(c for r, c in comp)]
            for comp in comps
        ]

    # For each color, take the unique non-background component that is itself
    # a 2x2 block. This gives the fill color for the rectangle it borders.
    block_color = None
    for color, boxes in groups.items():
        exact = [b for b in boxes if (b[1] - b[0] + 1) * (b[3] - b[2] + 1) == 4]
        if len(exact) == 1:
            block_color = color
            block_box = exact[0]
            break

    if block_color is None:
        return [[int(x) for x in row] for row in g]

    others = []
    for color, boxes in groups.items():
        if color == block_color:
            continue
        for r1, r2, c1, c2 in boxes:
            if (r1, c1) in block_box or (r2, c2) in block_box or \
               (r1, c2) in block_box or (r2, c1) in block_box:
                others.append((r1, r2, c1, c2))

    if not others:
        return [[int(x) for x in row] for row in g]

    tr = min(b[0] for b in others)
    br = max(b[1] for b in others)
    tc = min(b[2] for b in others)
    bc = max(b[3] for b in others)

    out = g.copy()
    for r in range(tr, br + 1):
        for c in range(tc, bc + 1):
            if out[r, c] == background:
                out[r, c] = block_color

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    def count_color(x):
        return int(np.count_nonzero(g == x))

    # Background is the most frequent colour.
    bg = int(np.argmax([0] + [count_color(c) for c in range(1, 10)]))

    out = g.copy()

    def flood_fill(start, value, target=bg):
        if not (0 <= start[0] < H and 0 <= start[1] < W):
            return
        if out[start[0], start[1]] != target:
            return
        q = deque([start])
        out[start[0], start[1]] = value
        while q:
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < H and 0 <= nc < W and out[nr, nc] == target:
                    out[nr, nc] = value
                    q.append((nr, nc))

    # Process every non-background colour.
    # If a colour has exactly one component whose bounding box is exactly 3x2
    # or 2x3 and the other component of that colour touches the side that
    # the 3x2/2x3 component does not, fill the target-background cell just
    # outside the bounding box, on the side opposite the touching component.
    for color in range(1, 10):
        if color == bg:
            continue
        if count_color(color) != 3:
            continue

        cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == color]
        seen = set()
        comps = []
        for cell in cells:
            if cell in seen:
                continue
            q = deque([cell])
            seen.add(cell)
            comp = [cell]
            while q:
                r, c = q.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if (nr, nc) in cells and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        comp.append((nr, nc))
                        q.append((nr, nc))
            comps.append(comp)

        if len(comps) != 2:
            continue

        boxes = []
        for comp in comps:
            rmin = min(r for r, _ in comp)
            rmax = max(r for r, _ in comp)
            cmin = min(c for _, c in comp)
            cmax = max(c for _, c in comp)
            boxes.append((rmin, rmax, cmin, cmax))

        target_boxes = []
        for i, (r1, r2, c1, c2) in enumerate(boxes):
            other = boxes[1 - i]
            wr, hc = r2 - r1 + 1, c2 - c1 + 1
            if (wr, hc) not in ((3, 2), (2, 3)):
                continue

            touches = set()
            for (or1, or2, oc1, oc2) in [other]:
                if r2 + 1 == or1:
                    touches.add('B')
                if r1 - 1 == or2:
                    touches.add('T')
                if c2 + 1 == oc1:
                    touches.add('R')
                if c1 - 1 == oc2:
                    touches.add('L')

            for side in ('T', 'B', 'L', 'R'):
                if side in touches:
                    continue
                if side == 'T':
                    fill = (r1 - 1, c1, c2)
                elif side == 'B':
                    fill = (r2 + 1, c1, c2)
                elif side == 'L':
                    fill = (r1, r2, c1 - 1)
                elif side == 'R':
                    fill = (r1, r2, c2 + 1)

                if 0 <= fill[0] < H and (0 <= fill[1] < W if len(fill) == 2 else True):
                    target_boxes.append((i, side, fill))
                    break

        for i, side, fill in target_boxes:
            if side in ('T', 'B'):
                row, c1, c2 = fill
                for c in range(c1, c2 + 1):
                    flood_fill((row, c), color)
            else:
                r1, r2, col = fill
                for r in range(r1, r2 + 1):
                    flood_fill((r, col), color)

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine background as the most frequent color.
    colors = np.unique(g)
    bg = int(max(colors, key=lambda c: np.count_nonzero(g == c)))

    def connected_components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for r in range(h):
            for c in range(w):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    comp = [(r, c)]
                    while q:
                        y, x = q.popleft()
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                                comp.append((ny, nx))
                    comps.append(comp)
        return comps

    # Find fill color: exactly two components, both singletons.
    fill_color = None
    for color in range(1, 10):
        if color == bg:
            continue
        comps = connected_components(g == color)
        if len(comps) == 2 and all(len(comp) == 1 for comp in comps):
            fill_color = color
            break

    if fill_color is None:
        return [[int(v) for v in row] for row in g]

    # Walls are all non-background pixels.
    wall = (g != bg)

    # Find background cells not connected to the border.
    outside = np.zeros((h, w), dtype=bool)
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if not wall[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    for c in range(w):
        for r in (0, h - 1):
            if not wall[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not wall[nr, nc] and not outside[nr, nc]:
                outside[nr, nc] = True
                q.append((nr, nc))

    # Enclosed background cells become the fill color.
    result = g.copy()
    enclosed = (~wall) & (~outside)
    result[enclosed] = fill_color

    return [[int(v) for v in row] for row in result]

