            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen_h:
                    if (ny, nx) in cell_set:
                        continue
                    seen_h.add((ny, nx))
                    q.append((ny, nx))
        return True

    def set_boundary_around(cells):
        """
        Paint 2 on all background cells 8-neighbouring the component.
        """
        for y, x in cells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and out[ny][nx] == BG:
                        out[ny][nx] = 2

    for cells in comps:
        cell_set = set(cells)

        # Find all enclosed background cells associated with this component.
        holes = set()
        for y, x in cells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == BG:
                        if is_hole(p, cells):
                            holes.add(p)

        if holes:
            # Component encloses background:
            # - original component becomes 8
            # - enclosed background becomes 8
            # - largest enclosed background component becomes 6
            # - 8-neighbouring outside background becomes 2
            for y, x in cells:
                out[y][x] = 8
            for y, x in holes:
                out[y][x] = 8

            # Largest 4-connected hole component becomes 6.
            seen_hole = set()
            best = []
            for p in holes:
                if p in seen_hole:
                    continue
                q = deque([p])
                seen_hole.add(p)
                cur = []
                while q:
                    y, x = q.popleft()
                    cur.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        np_ = (y + dy, x + dx)
                        if np_ in holes and np_ not in seen_hole:
                            seen_hole.add(np_)
                            q.append(np_)
                if len(cur) > len(best):
                    best = cur

            for y, x in best:
                out[y][x] = 6

            set_boundary_around(cells)
        else:
            # Component does not enclose background:
            # keep its original pixels and paint 2 on its 8-neighbour boundary.
            set_boundary_around(cells)

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    N = W // 2
    out = g.copy()

    def get_quadrant(qr, qc):
        r0, c0 = qr * N, qc * N
        return g[r0+1:r0+N-1, c0+1:c0+N-1]

    def get_bbox(region):
        mask = region != 4
        if not mask.any():
            return None
        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        return int(rows[0]), int(rows[-1]), int(cols[0]), int(cols[-1])

    def get_marker_bbox(region):
        mask = (region == 2)
        if not mask.any():
            return None
        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        return int(rows[0]), int(rows[-1]), int(cols[0]), int(cols[-1])

    quadrants = [get_quadrant(r, c) for r in range(2) for c in range(2)]
    bboxes = [get_bbox(q) for q in quadrants]

    # Find source quadrant (largest non-4 region)
    sizes = []
    for bb in bboxes:
        if bb is None:
            sizes.append(0)
        else:
            sizes.append((bb[1]-bb[0]+1) * (bb[3]-bb[2]+1))
    src = max(range(4), key=lambda i: sizes[i])

    sy0, sy1, sx0, sx1 = bboxes[src]
    Hs = sy1 - sy0 + 1
    Ws = sx1 - sx0 + 1
    src_shape = quadrants[src][sy0:sy1+1, sx0:sx1+1].copy()

    for i in range(4):
        if i == src:
            continue
        marker = get_marker_bbox(quadrants[i])
        if marker is None:
            continue
        my0, my1, mx0, mx1 = marker
        Hm = my1 - my0 + 1
        Wm = mx1 - mx0 + 1

        # Determine transform type
        sq, dq = divmod(src, 2), divmod(i, 2)
        if sq == dq:
            t = 'rot180'
        elif sq[0] == dq[0]:
            t = 'hmirror'
        else:
            t = 'vmirror'

        # Apply transform to source pattern
        if t == 'hmirror':
            tshape = src_shape[:, ::-1]
        elif t == 'vmirror':
            tshape = src_shape[::-1, :]
        else:
            tshape = src_shape[::-1, ::-1]

        # Create destination pattern fitted to marker bbox
        dest = np.full((Hm, Wm), 4, dtype=int)
        for r in range(Hm):
            for c in range(Wm):
                sr = r * Hs // Hm
                sc = c * Ws // Wm
                dest[r, c] = tshape[sr, sc]

        # Place into output
        qr, qc = divmod(i, 2)
        r0, c0 = qr * N, qc * N
        out[r0+1+my0:r0+1+my1+1, c0+1+mx0:c0+1+mx1+1] = dest

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    # Background: most frequent colour in the input.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    nonbg = g != bg
    if not np.any(nonbg):
        return [[bg] * w for _ in range(h)]

    # 8-connected components of non-background pixels.
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if nonbg[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if nonbg[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                colors = set(int(g[y, x]) for y, x in cells)
                ys = [y for y, _ in cells]
                xs = [x for _, x in cells]
                comps.append({
                    "cells": cells,
                    "colors": colors,
                    "y0": min(ys), "y1": max(ys),
                    "x0": min(xs), "x1": max(xs),
                    "area": len(cells),
                    "bbox_area": (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1),
                })

    # Pick the mask component as the monochrome component; otherwise fall back
    # to the smaller/sparser component.
    mono = [c for c in comps if len(c["colors"]) == 1]
    if len(mono) == 1:
        mask = mono[0]
    elif len(mono) >= 2:
        mask = min(mono, key=lambda c: (c["area"], c["bbox_area"], c["y0"], c["x0"]))
    else:
        mask = min(comps, key=lambda c: (c["area"], c["bbox_area"], c["y0"], c["x0"]))

    mask_colors = mask["colors"]
    sprite = None
    for c in comps:
        if c is mask:
            continue
        if len(c["colors"]) > 1:
            if sprite is None or c["bbox_area"] > sprite["bbox_area"]:
                sprite = c
        else:
            if sprite is None or (c["area"] < sprite["area"]):
                sprite = c

    if sprite is None:
        # Degenerate fallback: tile the mask by itself.
        sprite = mask

    sy0, sy1 = sprite["y0"], sprite["y1"]
    sx0, sx1 = sprite["x0"], sprite["x1"]
    sh = sy1 - sy0 + 1
    sw = sx1 - sx0 + 1

    my0, my1 = mask["y0"], mask["y1"]
    mx0, mx1 = mask["y0"] if False else mask["x0"]  # placeholder to avoid lint; fixed below
    mx0 = mask["x0"]
    mx1 = mask["x1"]
    mh = my1 - my0 + 1
    mw = mx1 - mx0 + 1

    out = np.full((mh * sh, mw * sw), bg, dtype=int)

    sprite_patch = g[sy0:sy1 + 1, sx0:sx1 + 1].copy()

    # Boolean mask over the mask component's bounding box.
    mask_patch = np.zeros((mh, mw), dtype=bool)
    for y, x in mask["cells"]:
        mask_patch[y - my0, x - mx0] = True

    for i in range(mh):
        for j in range(mw):
            if mask_patch[i, j]:
                r0 = i * sh
                c0 = j * sw
                out[r0:r0 + sh, c0:c0 + sw] = sprite_patch

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    H = len(grid)
    W = len(grid[0]) if H else 0
    A = np.array(grid, dtype=int)

    def is_background(c: int) -> bool:
        return int((A == c).sum()) > (H * W) // 2

    def is_frame_box(r1, r2, c1, c2, border):
        if r2 - r1 < 1 or c2 - c1 < 1:
            return False
        sub = A[r1:r2 + 1, c1:c2 + 1]
        if not np.all(sub[0, :] == border) or not np.all(sub[-1, :] == border):
            return False
        if not np.all(sub[:, 0] == border) or not np.all(sub[:, -1] == border):
            return False
        if r2 - r1 == 1 and c2 - c1 == 1:
            return True
        inner = sub[1:-1, 1:-1]
        vals = set(int(x) for x in inner.flatten())
        return len(vals) == 1 and border not in vals

    def box_color(r1, r2, c1, c2, border):
        return int(A[r1 + 1, c1 + 1]) if (r2 - r1 >= 1 and c2 - c1 >= 1) else border

    def draw_box(out, r1, c1, size, border, inner):
        for dr in range(size + 1):
            for dc in range(size + 1):
                r, c = r1 + dr, c1 + dc
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = border if dr == 0 or dr == size or dc == 0 or dc == size else inner

    def move_component(comp, bg, out, occupied):
        if len(comp) != 1:
            return
        r1 = min(r for r, c in comp)
        r2 = max(r for r, c in comp)
        c1 = min(c for r, c in comp)
        c2 = max(c for r, c in comp)
        borders = set(int(A[r, c]) for r, c in comp if A[r, c] != bg)
        if len(borders) != 1:
            return
        border = borders.pop()
        if not is_frame_box(r1, r2, c1, c2, border):
            return
        size = r2 - r1
        if size <= 0:
            return
        inner = box_color(r1, r2, c1, c2, border)

        best = None
        for dx in range(0, W - c2 + 1):
            for dy in range(0, H - r2 + 1):
                oc = c1 + dx
                if oc + size < 0 or oc + size >= W:
                    continue
                ok = True
                for rr in range(r1, r2 + 1):
                    for cc in range(oc, oc + size + 1):
                        if occupied[rr, cc] and not occupied[rr, cc + size + 1]:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                score = (dx, dy)
                if best is None or score < best[0]:
                    best = (score, oc)

        if best is None:
            return

        new_c = best[1]
        for r in range(r1, r2 + 1):
            for c in range(new_c, new_c + size + 1):
                occupied[r, c] = True
        draw_box(out, r1, new_c, size, border, inner)

    # If the grid is uniform, return it unchanged.
    if len(set(int(x) for x in A.flatten())) == 1:
        return [[int(x) for x in row] for row in A.tolist()]

    candidates = sorted(set(int(x) for x in A.flatten()),
                        key=lambda c: (int((A == c).sum()), c))
    chosen_bg = None
    for bg in candidates:
        if not is_background(bg):
            continue

        vis = np.zeros((H, W), dtype=bool)
        comps = []
        for sr in range(H):
            for sc in range(W):
                if A[sr, sc] == bg or vis[sr, sc]:
                    continue
                q = deque([(sr, sc)])
                vis[sr, sc] = True
                comp = []
                while q:
                    r, c = q.popleft()
                    comp.append((r, c))
                    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                        if 0 <= nr < H and 0 <= nc < W and not vis[nr, nc] and A[nr, nc] != bg:
                            vis[nr, nc] = True
                            q.append((nr, nc))
                comps.append(comp)

        occupied = np.zeros((H, W + 1), dtype=bool)
        for comp in comps:
            for r, c in comp:
                occupied[r, c] = True

        out = np.full((H, W), bg, dtype=int)
        # Move smaller/earlier components first; they keep their leftmost possible place.
        for comp in sorted(comps, key=len):
            move_component(comp, bg, out, occupied)

        if (out == A).all():
            return [[int(x) for x in row] for row in out.tolist()]
        chosen_bg = bg
        break

    # Fallback: if no background produced a change, return the input.
    return [[int(x) for x in row] for row in A.tolist()]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    H = len(grid)
    W = len(grid[0]) if H else 0
    A = np.array(grid, dtype=int)

    def is_box(r1, r2, c1, c2):
        if r2 - r1 < 1 or c2 - c1 < 1:
            return None
        b = int(A[r1, c1])
        if not np.all(A[r1, c1:c2 + 1] == b):
            return None
        if not np.all(A[r2, c1:c2 + 1] == b):
            return None
        if not np.all(A[r1:r2 + 1, c1] == b):
            return None
        if not np.all(A[r1:r2 + 1, c2] == b):
            return None
        inner = A[r1 + 1:r2, c1 + 1:c2]
        vals = set(int(x) for x in inner.flatten())
        if len(vals) != 1:
            return None
        return (r1, r2, c1, c2, b, vals.pop())

    boxes = []
    for r1 in range(H):
        for r2 in range(r1 + 1, H):
            for c1 in range(W):
                for c2 in range(c1 + 1, W):
                    info = is_box(r1, r2, c1, c2)
                    if info:
                        boxes.append(info)

    # Choose the minimal set of boxes that exactly covers all non-background cells.
    # In these puzzles the input consists of a few frame/inner squares; the minimal
    # exact cover is the intended set of objects.
    def minimal_cover(boxes):
        if not boxes:
            return []
        mask_cells = {}
        for idx, b in enumerate(boxes):
            r1, r2, c1, c2 = b[0], b[1], b[2], b[3]
            cells = []
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    cells.append((r, c))
            mask_cells[idx] = cells

        used_idx = []
        for b in boxes:
            used_idx.append(b[0] * W + b[2] * 3 + b[1] * 31 + b[3])  # placeholder not used

        best = None
        # For these sizes, exhaustive subset over unique boxes is fine.
        # But to be safe, use a simple branch and bound.
        masks = list(mask_cells.values())
        n = len(masks)
        all_set = set()
        for m in masks:
            all_set.update(m)

        # Sort boxes by rarest cell coverage (cells appearing in few boxes first)
        cell_count = {}
        for idx, m in enumerate(masks):
            for cell in m:
                cell_count[cell] = cell_count.get(cell, 0) + 1
        boxes_sorted = sorted(range(n), key=lambda i: (min(cell_count[c] for c in masks[i]), len(masks[i])))

        best_size = n + 1
        best_set = None

        def dfs(pos, chosen, covered):
            nonlocal best_size, best_set
            if best_set is not None and len(chosen) >= best_size:
                return
            if len(covered) == len(all_set):
                if len(chosen) < best_size:
                    best_size = len(chosen)
                    best_set = set(chosen)
                return
            if pos == len(boxes_sorted):
                return
            # If remaining boxes cannot cover enough cells, prune
            # choose or skip boxes_sorted[pos]
            i = boxes_sorted[pos]
            # choose
            new_covered = covered | set(masks[i])
            dfs(pos + 1, chosen + [i], new_covered)
            # skip
            dfs(pos + 1, chosen, covered)

        dfs(0, [], set())
        if best_set is None:
            # Fallback: choose the smallest boxes (likely objects)
            return boxes
        return [boxes[i] for i in sorted(best_set)]

    boxes = minimal_cover(boxes)

    if not boxes:
        return [[int(x) for x in row] for row in A.tolist()]

    bg = int(np.bincount(A.flatten()).argmax())
    out = np.full((H, W), bg, dtype=int)

    def draw(box):
        r1, r2, c1, c2, b, inner = box
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = b if r == r1 or r == r2 or c == c1 or c == c2 else inner

    def valid(box):
        r1, r2, c1, c2 = box[0], box[1], box[2], box[3]
        if r1 < 0 or r2 >= H or c1 < 0 or c2 >= W:
            return False
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if out[r, c] != bg:
                    return False
        return True

    # Deterministic order: from top to bottom, then left to right.
    # Move each box right by one if possible; this reproduces all provided examples.
    order = sorted(range(len(boxes)), key=lambda i: (boxes[i][0], boxes[i][2]))
    for i in order:
        r1, r2, c1, c2, b, inner = boxes[i]
        placed = False
        for dc in range(0, W - c1):
            cand = (r1, r2, c1 + dc, c2 + dc, b, inner)
            if valid(cand):
                draw(cand)
                placed = True
                break
        if not placed:
            # should not happen for valid ARC inputs
            draw(boxes[i])

    return [[int(x) for x in row] for row in out.tolist()]

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [[0]*W for _ in range(H)]

    # Detect all frame boxes (border + uniform inner, min size 3x3)
    boxes = []
    for r1 in range(H - 2):
        for c1 in range(W - 2):
            b = grid[r1][c1]
            if b == 0:
                continue
            for size in range(3, min(H - r1, W - c1) + 1):
                r2, c2 = r1 + size - 1, c1 + size - 1
                ok = True
                # Check border
                for c in range(c1, c2 + 1):
                    if grid[r1][c] != b or grid[r2][c] != b:
                        ok = False; break
                if ok:
                    for r in range(r1, r2 + 1):
                        if grid[r][c1] != b or grid[r][c2] != b:
                            ok = False; break
                if ok and size > 3:
                    inner = grid[r1+1][c1+1]
                    uniform = True
                    for r in range(r1+1, r2):
                        for c in range(c1+1, c2):
                            if grid[r][c] != inner:
                                uniform = False; break
                        if not uniform: break
                    if uniform:
                        continue  # try larger
                if ok:
                    inner = grid[r1+1][c1+1] if size > 3 else b
                    boxes.append((r1, r2, c1, c2, b, inner))
                    break  # smallest box at this corner

    # Sort: larger size first, then top row, then left col
    boxes.sort(key=lambda x: (-(x[1]-x[0]), x[0], x[2]))

    # Place each box as far right as possible without overlapping
    placed = []
    for r1, r2, c1, c2, b, inner in boxes:
        size = r2 - r1
        max_c1 = W - size - 1
        found = False
        for nc1 in range(max_c1, -1, -1):
            nc2 = nc1 + size
            overlap = False
            for pr1, pr2, pc1, pc2 in placed:
                if not (r2 < pr1 or r1 > pr2 or nc2 < pc1 or nc1 > pc2):
                    overlap = True
                    break
            if not overlap:
                for r in range(r1, r2+1):
                    for c in range(nc1, nc2+1):
                        out[r][c] = b if r==r1 or r==r2 or c==nc1 or c==nc2 else inner
                placed.append((r1, r2, nc1, nc2))
                found = True
                break
        if not found:
            for r in range(r1, r2+1):
                for c in range(c1, c2+1):
                    out[r][c] = b if r==r1 or r==r2 or c==c1 or c==c2 else inner
            placed.append((r1, r2, c1, c2))

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import defaultdict

    H = len(grid)
    W = len(grid[0])

    def is_frame(r1, c1, size, border):
        r2 = r1 + size - 1
        c2 = c1 + size - 1
        if r2 >= H or c2 >= W:
            return False

        if any(grid[r1][c] != border for c in range(c1, c2 + 1)):
            return False
        if any(grid[r2][c] != border for c in range(c1, c2 + 1)):
            return False
        if any(grid[r][c1] != border for r in range(r1 + 1, r2)):
            return False
        if any(grid[r][c2] != border for r in range(r1 + 1, r2)):
            return False

        inner = grid[r1 + 1][c1 + 1]
        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                if grid[r][c] != inner:
                    return False
        return True

    tiles = []
    seen = [[False] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if seen[r][c]:
                continue
            if grid[r][c] == 0:
                continue

            border = grid[r][c]
            found = False
            for size in range(3, min(H - r, W - c) + 1):
                if is_frame(r, c, size, border):
                    r2 = r + size - 1
                    c2 = c + size - 1
                    inner = grid[r + 1][c + 1] if size > 2 else border
                    tiles.append({
                        "r1": r,
                        "c1": c,
                        "size": size,
                        "border": border,
                        "inner": inner,
                    })
                    for rr in range(r, r2 + 1):
                        for cc in range(c, c2 + 1):
                            seen[rr][cc] = True
                    found = True
                    break

            if found:
                continue

            # Any non-background pixel not covered by a tile is treated as
            # isolated and left in place.
            tiles.append({
                "r1": r,
                "c1": c,
                "size": 1,
                "border": grid[r][c],
                "inner": grid[r][c],
                "single": True,
            })
            seen[r][c] = True

    # Pack only real framed tiles. Single pixels are copied back directly.
    packables = [t for t in tiles if "single" not in t]
    singles = [t for t in tiles if "single" in t]

    # Group by top row. Each row band is packed independently.
    by_row = defaultdict(list)
    for t in packables:
        by_row[t["r1"]].append(t)

    out = [[0] * W for _ in range(H)]

    def draw_tile(t, c1):
        r1 = t["r1"]
        size = t["size"]
        r2 = r1 + size - 1
        c2 = c1 + size - 1
        border = t["border"]
        inner = t["inner"]

        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if r == r1 or r == r2 or c == c1 or c == c2:
                    out[r][c] = border
                else:
                    out[r][c] = inner

    for r1 in sorted(by_row):
        row_tiles = sorted(by_row[r1], key=lambda t: t["c1"])
        placed = []

        for t in row_tiles:
            size = t["size"]
            max_c1 = W - size
            ok = False
            for c1 in range(max_c1 + 1):
                c2 = c1 + size - 1
                collision = False
                for pr1, pc1, psize in placed:
                    if not (r1 + size - 1 < pr1 or r1 > pr1 + psize - 1 or
                            c2 < pc1 or c1 > pc1 + psize - 1):
                        collision = True
                        break
                if not collision:
                    draw_tile(t, c1)
                    placed.append((r1, c1, size))
                    ok = True
                    break

            if not ok:
                draw_tile(t, t["c1"])

    for t in singles:
        out[t["r1"]][t["c1"]] = t["border"]

    return out

