def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    out = np.zeros((h, w), dtype=int)

    # Identify the main "spine" as the connected component (4-neighbor) of 8s
    # that contains an 8 in the first row (or leftmost/topmost 8 if none).
    eight = (g == 8)
    comps = []
    seen = np.zeros_like(eight, dtype=bool)
    for r in range(h):
        for c in range(w):
            if eight[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and eight[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)

    if not comps:
        return out.tolist()

    # Prefer the component touching the top edge; otherwise choose the largest.
    top_comps = [cells for cells in comps if any(y == 0 for y, _ in cells)]
    if top_comps:
        spine = top_comps[0]
    else:
        spine = max(comps, key=len)

    # Collect colors associated with the spine: any non-8 color orthogonally
    # adjacent to the spine.  If there is exactly one, that is the output color.
    adj_colors = set()
    for y, x in spine:
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < h and 0 <= nx < w:
                v = int(g[ny, nx])
                if v != 0 and v != 8:
                    adj_colors.add(v)

    if len(adj_colors) == 1:
        color = adj_colors.pop()
    elif len(adj_colors) > 1:
        # In the visible/test instances this does not happen for the top spine,
        # but keep a robust fallback.
        color = min(adj_colors)
    else:
        return out.tolist()

    # The visible transformation draws a 45-degree diamond/ellipse around the
    # topmost point of the spine.  The radius is the vertical span of the spine
    # from that top point, plus one.  This exactly reproduces the examples.
    top = min(spine, key=lambda p: (p[0], p[1]))
    y0, x0 = top
    R = max(abs(y - y0) for y, _ in spine) + 1

    for dy in range(-R, R + 1):
        for dx in range(-R, R + 1):
            if abs(dy) + abs(dx) == R:
                y, x = y0 + dy, x0 + dx
                if 0 <= y < h and 0 <= x < w:
                    out[y, x] = color

    return out.tolist()

