def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])

    out = [row[:] for row in grid]

    # Count occurrences of each color.
    freq = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            freq[v] = freq.get(v, 0) + 1

    non_bg = [color for color in freq if color != 0 and freq[color] <= 5]

    # The wall color is the rare color that is not the seed.
    wall = None
    seed = None
    for color in non_bg:
        if freq[color] == 1:
            seed = color
        else:
            wall = color

    if seed is None or wall is None:
        return out

    # Flood fill 4-connected background cells starting from the single seed,
    # blocked by the wall color.
    for sr in range(H):
        for sc in range(W):
            if grid[sr][sc] == seed:
                q = deque([(sr, sc)])
                seen = {(sr, sc)}
                out[sr][sc] = seed
                while q:
                    r, c = q.popleft()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in seen:
                            if grid[nr][nc] == wall:
                                continue
                            if grid[nr][nc] == 0:
                                seen.add((nr, nc))
                                out[nr][nc] = seed
                                q.append((nr, nc))

    return out

