from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    G = [list(map(int, row)) for row in grid]

    # If the grid is empty or has only one colour, nothing to do.
    colors = set()
    for row in G:
        for v in row:
            colors.add(v)
    if len(colors) <= 1:
        return G

    # Most frequent colour is the background that may be filled.
    bg = max(colors, key=lambda x: sum(row.count(x) for row in G))

    # Candidate wall colours: non-background colours that are not singletons.
    candidates = []
    for c in colors:
        if c == bg:
            continue
        cnt = sum(row.count(c) for row in G)
        if 1 < cnt < 100:
            candidates.append(c)

    def flood4(start, wall):
        if not (0 <= start[0] < H and 0 <= start[1] < W):
            return None
        s0, s1 = start
        if G[s0][s1] != bg:
            return None
        seen = [[False] * W for _ in range(H)]
        q = deque([start])
        seen[s0][s1] = True
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc]:
                    if G[nr][nc] != wall and G[nr][nc] == bg:
                        seen[nr][nc] = True
                        q.append((nr, nc))
        return seen

    best = None
    best_score = -10**9

    # Try every single-cell seed and every candidate wall colour.
    for sr in range(H):
        for sc in range(W):
            for w in candidates:
                if G[sr][sc] == w:
                    continue
                seed_color = G[sr][sc]
                if seed_color == bg:
                    continue

                seen = flood4((sr, sc), w)
                if seen is None:
                    continue

                # The filled component should contain the seed.
                if not seen[sr][sc]:
                    continue

                score = 0
                # Encourages a nontrivial connected region.
                score += 10 * sum(row.count(True) for row in seen)

                # Strong penalty if a wall cell lies strictly inside the filled area
                # in the same row segment between two filled cells.
                for r in range(H):
                    run_start = -1
                    for c in range(1, W + 1):
                        if c < W and seen[r][c]:
                            if run_start == -1:
                                run_start = c
                        else:
                            if run_start != -1:
                                # Check the row between run_start and c-1.
                                # Wall cells outside the run are allowed,
                                # but walls separating filled cells are bad.
                                # We only need to inspect cells inside the run.
                                for cc in range(run_start, c):
                                    if G[r][cc] == w:
                                        # wall inside filled run
                                        score -= 1000
                                run_start = -1
                if score > best_score:
                    best_score = score
                    best = (w, seed_color, seen)

    if best is None:
        return G

    wall, seed_color, seen = best
    out = [row[:] for row in G]
    for r in range(H):
        for c in range(W):
            if seen[r][c] and out[r][c] == bg:
                out[r][c] = seed_color
    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])

    # Count colors
    freq = {}
    for r in range(H):
        for c in range(W):
            freq[grid[r][c]] = freq.get(grid[r][c], 0) + 1

    bg = max(freq, key=lambda x: freq[x])

    # Find wall and seed among non-bg colors
    # Wall: the color that forms the barrier (higher count among non-bg, non-seed)
    # Seed: the color that gets propagated (lower count, often 1-6)
    non_bg = {c: n for c, n in freq.items() if c != bg}

    if not non_bg:
        return [row[:] for row in grid]

    # The seed is the rarest non-bg color (smallest count)
    # The wall is the next most common non-bg color
    sorted_non_bg = sorted(non_bg.items(), key=lambda x: x[1])
    seed = sorted_non_bg[0][0]
    wall = sorted_non_bg[1][0] if len(sorted_non_bg) > 1 else None

    if wall is None:
        return [row[:] for row in grid]

    # Find all seed positions
    seeds = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == seed:
                seeds.append((r, c))

    # Flood fill from seeds through bg cells, blocked by wall cells.
    # Other non-bg, non-wall cells also block (not overwritten, not passable).
    out = [row[:] for row in grid]
    visited = [[False]*W for _ in range(H)]
    q = deque()

    for (sr, sc) in seeds:
        q.append((sr, sc))
        visited[sr][sc] = True

    while q:
        r, c = q.popleft()
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                if grid[nr][nc] == bg:
                    visited[nr][nc] = True
                    out[nr][nc] = seed
                    q.append((nr, nc))

    return out

